insert into public.recipes as saved
  (id, name, category, difficulty, prep_time, bake_time, servings, pan, rating, diet, ingredients, instructions, source, tested, owner)
values
  (1, 'Supersized Soft Chocolate Chip Cookies', 'cookies', 'medium', 35, 20, 17, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":226,"unit":"g"},{"name":"light brown sugar","amount":426,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"bread flour","amount":330,"unit":"g"},{"name":"whole milk","amount":113,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"semisweet chocolate, chopped","amount":340,"unit":"g"}]'::jsonb, array['Brown the butter in a pan until it smells nutty and flecks turn golden, about 6 minutes. Pour it over the brown sugar and salt in a large bowl and whisk.', 'Whisk 23 g of the flour with the milk in the same pan over low heat until it thickens into a paste. Scrape it into the bowl.', 'Whisk in the eggs and vanilla, then stir in the rest of the flour, baking powder and baking soda.', 'Rest the dough 10 minutes, then fold in the chopped chocolate.', 'Cover and chill the dough for 24 to 72 hours. This deepens the flavour and keeps the cookies thick.', 'Heat the oven to 175°C. Let the dough stand 10 minutes, then scoop 85 g mounds, about 8 cm apart, onto lined trays.', 'Bake 18 to 22 minutes, turning the tray halfway, until the edges are set and the middles still look soft.', 'Cool on the tray for 15 minutes before moving.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/supersized-super-soft-chocolate-chip-cookies-recipe"}'::jsonb, false, null),
  (2, 'Buttery Snickerdoodles', 'cookies', 'easy', 15, 9, 48, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":149,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":160,"unit":"g"},{"name":"sugar for rolling","amount":25,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line two trays.', 'Beat the soft butter and sugar until smooth, then beat in the egg.', 'Mix in the vanilla, salt and baking powder, then the flour, until no dry patches remain.', 'Shake the rolling sugar and cinnamon together in a bag or bowl.', 'Roll the dough into 2.5 cm balls and coat them in the cinnamon sugar.', 'Place 4 cm apart and flatten each to about 1 cm.', 'Bake 8 minutes for soft cookies or 10 for crisp ones. Cool on the tray, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/buttery-snickerdoodles-recipe"}'::jsonb, false, null),
  (3, 'Soft Oatmeal Raisin Cookies', 'cookies', 'medium', 35, 13, 16, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"whole milk","amount":76,"unit":"g"},{"name":"rolled oats","amount":178,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":90,"unit":"g"},{"name":"baking powder","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":2,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"raisins","amount":149,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line two trays with parchment.', 'Warm the butter and milk until the butter melts and the edges bubble. Stir in the oats and leave 5 minutes to soak up the liquid.', 'Whisk the brown sugar, egg and vanilla for a minute until creamy.', 'Stir the soaked oats into the egg mixture.', 'Add the flour, baking powder, cinnamon and salt and mix until no dry streaks remain, then fold in the raisins.', 'Scoop 53 g portions, eight to a tray, and bake one tray at a time for 12 to 14 minutes until the edges are golden.', 'While hot, press a round cutter or jar lid around each cookie and swirl it to neaten the edges. Cool on the tray.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/the-softest-oatmeal-raisin-cookies-recipe"}'::jsonb, false, null),
  (4, 'Classic Shortbread', 'cookies', 'easy', 15, 38, 16, 'round-23', null, array['vegetarian']::text[], '[{"name":"salted butter","amount":227,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C. Grease a 23 cm round tin and line it with parchment.', 'Beat the butter, icing sugar, vanilla and salt until smooth.', 'Add the flour and mix until a stiff dough forms. If it will not come together, add a spoonful of water.', 'Press the dough evenly into the tin and prick it all over with a fork.', 'Bake 35 to 40 minutes until pale gold on top and deeper gold at the edges.', 'Cool 5 to 10 minutes in the tin, then turn out and cut into wedges while still warm.', 'Cool the pieces on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/shortbread-recipe"}'::jsonb, false, null),
  (5, 'Classic Peanut Butter Cookies', 'cookies', 'easy', 15, 14, 24, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"creamy peanut butter","amount":198,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"salt","amount":3,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line two trays.', 'Beat the butter, both sugars, egg, vanilla and peanut butter until smooth.', 'Mix in the flour, baking soda and salt. The dough is stiff.', 'Scoop tablespoon-sized balls, 5 cm apart.', 'Press each flat to about 1 cm with a fork, once each way to make a crisscross.', 'Bake 12 to 16 minutes until the edges colour and the tops stay pale.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-peanut-butter-cookies-recipe"}'::jsonb, false, null),
  (6, 'Gingerbread Cookies', 'cookies', 'medium', 35, 9, 36, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":170,"unit":"g"},{"name":"brown sugar","amount":159,"unit":"g"},{"name":"molasses","amount":255,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"ground ginger","amount":4,"unit":"g"},{"name":"ground cloves","amount":1,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":450,"unit":"g"}]'::jsonb, array['Melt the butter and stir in the brown sugar, molasses, salt and spices.', 'Let it cool until lukewarm, then beat in the egg.', 'Whisk the baking powder and soda into the flour and stir it in. The dough will be soft and sticky: do not add extra flour.', 'Halve the dough, flatten each half into a thick rectangle, wrap and chill at least 1 hour.', 'Heat the oven to 175°C and line trays.', 'Roll the dough 3 to 6 mm thick and cut shapes, close together to waste less.', 'Bake 8 to 10 minutes until the edges darken slightly.', 'Cool on the trays, then on a rack, and decorate if you like.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/gingerbread-cookies-recipe"}'::jsonb, false, null),
  (7, 'Gingerbread Crinkle Cookies', 'cookies', 'easy', 20, 16, 15, null, null, array['vegetarian']::text[], '[{"name":"dark brown sugar","amount":160,"unit":"g"},{"name":"butter, melted","amount":71,"unit":"g"},{"name":"molasses","amount":64,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":200,"unit":"g"},{"name":"gingerbread spice mix","amount":4,"unit":"g"},{"name":"baking powder","amount":2,"unit":"g"},{"name":"baking soda","amount":1,"unit":"g"},{"name":"icing sugar","amount":57,"unit":"g"},{"name":"gingerbread spice mix, for coating","amount":2,"unit":"g"}]'::jsonb, array['Stir the brown sugar, melted butter, molasses, vanilla and salt together until smooth.', 'Mix in the egg, then the flour, spice, baking powder and baking soda until no dry spots remain.', 'Cover and chill 1 to 2 hours until firm.', 'Heat the oven to 175°C with racks in the upper and lower thirds, and line two trays.', 'Whisk the icing sugar with the coating spice.', 'Roll the dough into 40 g balls, coat each in the sugar mixture and set them on the trays.', 'Bake 15 to 18 minutes, swapping the trays halfway, until puffed and set in the middle. Cool completely on the trays.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/gingerbread-crinkle-cookies-recipe"}'::jsonb, false, null),
  (8, 'Soft Molasses Cookies', 'cookies', 'easy', 20, 12, 24, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"ground ginger","amount":2,"unit":"g"},{"name":"ground cloves","amount":0.6,"unit":"g"},{"name":"ground nutmeg","amount":0.7,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking soda","amount":2.3,"unit":"g"},{"name":"butter","amount":71,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"molasses","amount":170,"unit":"g"},{"name":"dark rum","amount":75,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line a tray.', 'Whisk the flour, spices, salt and baking soda.', 'Beat the butter and sugar, then beat in the molasses.', 'Add the dry mix and the rum in alternating portions, ending with the dry.', 'Scoop 4 cm balls onto the tray.', 'Bake 11 to 12 minutes, until the tops crack but the edges are still pale.', 'Cool on the tray. Store airtight while barely warm to keep them soft.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/soft-molasses-cookies-recipe"}'::jsonb, false, null),
  (9, 'Chocolate Crinkle Cookies', 'cookies', 'medium', 20, 11, 72, null, null, array['vegetarian']::text[], '[{"name":"bittersweet chocolate, chopped","amount":227,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":135,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"espresso powder (optional)","amount":4,"unit":"g"},{"name":"baking powder","amount":2,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"all-purpose flour","amount":200,"unit":"g"},{"name":"icing sugar for coating","amount":120,"unit":"g"}]'::jsonb, array['Melt the chocolate and butter together and stir smooth.', 'Beat the sugar, eggs, vanilla and espresso powder, then mix in the chocolate, baking powder, salt and flour.', 'Chill 2 to 3 hours or overnight until firm.', 'Heat the oven to 165°C and line trays.', 'Roll 3 cm balls of dough and coat them thickly in icing sugar.', 'Place 4 cm apart and bake 10 to 12 minutes, turning the trays halfway, until they flatten and crack.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/chocolate-crinkle-cookies-recipe"}'::jsonb, false, null),
  (10, 'Double Chocolate Chip Cookies', 'cookies', 'easy', 10, 9, 36, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":67,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"espresso powder (optional)","amount":2,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"Dutch-process cocoa","amount":21,"unit":"g"},{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"semisweet chocolate chips","amount":340,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line two trays.', 'Beat the butter, both sugars, baking soda, salt and espresso powder until smooth.', 'Beat in the egg and vanilla. It may look grainy, which is fine.', 'Mix in the cocoa, then add the flour a little at a time, mixing just until combined.', 'Stir in the chocolate chips.', 'Drop small spoonfuls 2.5 cm apart. Dip the spoon in cold water if the dough sticks.', 'Bake 7 to 9 minutes until barely set, then cool on the tray.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/double-chocolate-chip-cookies-recipe"}'::jsonb, false, null),
  (11, 'Almond Thumbprint Cookies', 'cookies', 'medium', 15, 18, 24, null, null, array['vegetarian']::text[], '[{"name":"almond flour","amount":48,"unit":"g"},{"name":"all-purpose flour","amount":210,"unit":"g"},{"name":"sugar","amount":100,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"butter","amount":170,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"milk","amount":10,"unit":"g"},{"name":"almond extract","amount":3,"unit":"g"},{"name":"thick jam","amount":85,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a tray with parchment.', 'Mix the almond flour, all-purpose flour, sugar and salt briefly.', 'Add the soft butter and mix about 3 minutes until it forms fine crumbs.', 'Add the egg, milk and almond extract and mix about a minute until a soft dough forms.', 'Roll tablespoon-sized balls and press a deep well into each.', 'Fill each well with about half a teaspoon of jam.', 'Bake 16 to 20 minutes until the bottoms are lightly browned. Cool on the tray, then a rack, and dust with icing sugar.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/almond-thumbprint-cookies-recipe"}'::jsonb, false, null),
  (12, 'Lemon Cookies', 'cookies', 'easy', 10, 12, 19, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"cornstarch","amount":3,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"lemon juice powder","amount":14,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"}]'::jsonb, array['Heat the oven to 175°C and line two trays.', 'Whisk the flour, cornstarch, baking powder, salt and lemon juice powder (or use 1 tablespoon of fresh lemon juice in the wet mix).', 'Cream the butter, both sugars and the lemon zest.', 'Beat in the vanilla and egg.', 'Mix in the dry ingredients until just combined.', 'Scoop tablespoon-sized portions 5 cm apart and flatten slightly.', 'Bake 11 to 13 minutes until golden, cool 2 minutes on the tray, then move to a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/lemon-cookies-recipe"}'::jsonb, false, null),
  (13, 'American-Style Vanilla Biscotti', 'cookies', 'medium', 15, 55, 35, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":85,"unit":"g"},{"name":"sugar","amount":131,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"vanilla extract","amount":10,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line a large tray.', 'Beat the butter, sugar, salt, vanilla and baking powder until creamy.', 'Beat in the eggs, then mix in the flour on low to a sticky dough.', 'With wet hands, shape two logs about 24 x 5 cm on the tray.', 'Bake 25 minutes, then lower the oven to 165°C.', 'Mist the hot logs with water, wait 5 minutes, then slice straight down into 1.5 to 2 cm pieces.', 'Stand the slices on their edges and bake 25 to 30 minutes more until dry and golden. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/american-style-vanilla-biscotti-recipe"}'::jsonb, false, null),
  (14, 'Brioche', 'bread', 'hard', 25, 35, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":330,"unit":"g"},{"name":"dry milk powder","amount":28,"unit":"g"},{"name":"sugar","amount":35,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"water","amount":57,"unit":"g"},{"name":"butter","amount":142,"unit":"g"}]'::jsonb, array['Mix everything except the butter with a dough hook for 7 to 10 minutes until smooth and stretchy.', 'Add the cool, soft butter a piece at a time, then knead 5 to 10 minutes more until the dough is soft and smooth.', 'Rise 1 hour, then chill for several hours or overnight.', 'Shape into a large round or two loaves and place in greased tins.', 'Rise 2.5 to 3 hours until doubled.', 'Bake loaves at 175°C for 30 to 35 minutes (a round starts at 200°C for 10 minutes, then 175°C) until the centre reaches 88°C.', 'Cool 10 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/brioche-recipe"}'::jsonb, false, null),
  (15, 'Classic Challah', 'bread', 'medium', 20, 28, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":495,"unit":"g"},{"name":"water","amount":170,"unit":"g"},{"name":"vegetable oil","amount":74,"unit":"g"},{"name":"honey","amount":63,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"salt","amount":9,"unit":"g"},{"name":"instant yeast","amount":12,"unit":"g"},{"name":"egg white, for glazing","amount":1,"unit":"count"},{"name":"poppy or sesame seeds (optional)","amount":5,"unit":"g"}]'::jsonb, array['Mix and knead the flour, water, oil, honey, eggs, yolk, salt and yeast into a soft, smooth dough. If very sticky, work in up to 30 g more flour.', 'Cover and rise about 2 hours until puffy.', 'Deflate, divide into three, and roll each piece into a 50 cm rope. Rest 10 minutes if they spring back.', 'Braid the ropes and set the loaf on a lined tray.', 'Cover and rise 60 to 90 minutes until very puffy. Heat the oven to 190°C.', 'Beat the egg white with a spoonful of cold water, brush over the loaf and add seeds.', 'Bake 25 to 30 minutes until deep golden and 88°C inside. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-challah-recipe"}'::jsonb, false, null),
  (16, 'Whole Wheat and Rye Sourdough Loaf', 'bread', 'medium', 22, 26, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"milk","amount":198,"unit":"g"},{"name":"sourdough starter","amount":227,"unit":"g"},{"name":"dark brown sugar","amount":28,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"caraway seeds","amount":3,"unit":"g"},{"name":"anise seeds","amount":2,"unit":"g"},{"name":"ground cardamom","amount":0.5,"unit":"g"},{"name":"rye flour","amount":53,"unit":"g"},{"name":"whole wheat flour","amount":57,"unit":"g"},{"name":"all-purpose flour","amount":225,"unit":"g"}]'::jsonb, array['Mix the yeast, lukewarm milk, starter, sugar, salt, seeds and cardamom. Beat in the rye flour until smooth.', 'Stir in the whole wheat flour, then add the all-purpose flour a little at a time until the dough is shaggy.', 'Knead about 8 minutes until smooth, elastic and just slightly tacky.', 'Rise in a covered greased bowl until doubled, 1.5 to 2 hours.', 'Deflate and shape into a round, an oval or a loaf for a 23 cm tin. Rise 45 to 60 minutes until puffy.', 'Heat the oven to 200°C.', 'Bake about 25 minutes until deep brown and hollow-sounding underneath. Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/marilyns-whole-wheat-and-rye-sourdough-bread-recipe"}'::jsonb, false, null),
  (17, 'Classic Banana Bread', 'quick bread', 'easy', 20, 70, 10, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"light brown sugar","amount":142,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"ground nutmeg","amount":1,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ripe bananas, mashed","amount":340,"unit":"g"},{"name":"apricot jam or marmalade (optional)","amount":64,"unit":"g"},{"name":"honey","amount":85,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":270,"unit":"g"},{"name":"chopped walnuts (optional)","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C and grease the tin.', 'Beat the soft butter with the sugar, vanilla, spices, baking soda, baking powder and salt until smooth.', 'Mix in the bananas, jam, honey and eggs. A few lumps are fine.', 'Fold in the flour and walnuts until just combined.', 'Spread in the tin and let it stand 10 minutes.', 'Bake 45 minutes, then lay foil loosely over the top.', 'Bake about 25 minutes more until a skewer shows a few moist crumbs.', 'Cool 10 minutes in the tin, then turn out onto a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/banana-bread-recipe"}'::jsonb, false, null),
  (18, 'Simple Zucchini Bread', 'quick bread', 'easy', 10, 60, 10, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":159,"unit":"g"},{"name":"milk or fruit juice","amount":28,"unit":"g"},{"name":"vegetable oil","amount":99,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"baking powder","amount":1,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"all-purpose flour","amount":210,"unit":"g"},{"name":"grated zucchini","amount":270,"unit":"g"},{"name":"walnuts, toasted and chopped","amount":85,"unit":"g"},{"name":"raisins or currants","amount":128,"unit":"g"},{"name":"brown sugar, for topping","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease the tin.', 'Beat the sugar, liquid, oil, eggs and vanilla until smooth.', 'Whisk the baking powder, soda, salt and cinnamon into the flour, then fold gently into the wet mix.', 'Pat the grated zucchini dry and fold it in with the walnuts and raisins.', 'Spread in the tin and sprinkle with the topping sugar.', 'Bake 55 to 65 minutes until a skewer comes out clean.', 'Cool 10 minutes in the tin, then fully on a rack before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/simple-zucchini-bread-recipe"}'::jsonb, false, null),
  (19, 'Irish Soda Bread', 'bread', 'easy', 10, 50, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"Irish-style or all-purpose flour","amount":276,"unit":"g"},{"name":"bread flour","amount":150,"unit":"g"},{"name":"sugar","amount":37,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"currants or raisins","amount":95,"unit":"g"},{"name":"cold butter","amount":57,"unit":"g"},{"name":"buttermilk","amount":302,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"melted butter, for brushing","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and grease a 23 cm round tin.', 'Whisk both flours, the sugar, baking soda, salt and fruit.', 'Rub in the cold butter until no large pieces remain.', 'Whisk the buttermilk and egg, stir into the dry mix, adding a spoonful more buttermilk if crumbly.', 'Knead briefly, shape into a flattened ball and set in the tin. Cut a 1 cm deep cross in the top.', 'Bake 45 to 55 minutes until golden and a skewer comes out clean.', 'Brush the hot loaf with melted butter.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/irish-soda-bread-recipe"}'::jsonb, false, null),
  (20, 'Cornbread', 'bread', 'easy', 15, 23, 9, 'square-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":210,"unit":"g"},{"name":"yellow cornmeal","amount":156,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"baking soda","amount":1,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"milk","amount":283,"unit":"g"},{"name":"butter, melted and cooled","amount":57,"unit":"g"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"}]'::jsonb, array['Heat the oven to 190°C and grease a 23 cm square tin.', 'Whisk the flour, cornmeal, sugar, baking powder, baking soda and salt.', 'Whisk the milk, melted butter, oil and egg in another bowl.', 'Pour the wet into the dry and stir just until combined.', 'Spread in the tin.', 'Bake 20 to 25 minutes until the edges pull from the tin and a skewer comes out clean.', 'Cool 5 minutes, then cut.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cornbread-recipe"}'::jsonb, false, null),
  (21, 'Cinnamon Raisin Bread', 'bread', 'medium', 15, 43, 12, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"milk","amount":170,"unit":"g"},{"name":"butter","amount":28,"unit":"g"},{"name":"raisins","amount":85,"unit":"g"},{"name":"rolled oats","amount":45,"unit":"g"},{"name":"light brown sugar","amount":50,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"instant yeast","amount":8,"unit":"g"},{"name":"water","amount":65,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"cinnamon sugar, for the top","amount":15,"unit":"g"}]'::jsonb, array['Mix and knead the milk, butter, raisins, oats, sugar, salt, cinnamon, yeast, water and flour into a smooth, soft dough.', 'Rise about 2 hours until puffy.', 'Shape into a log, place in a greased tin and tent. Rise 1.5 to 2 hours until it crowns 3 to 4 cm over the rim. Heat the oven to 175°C.', 'Brush the top with milk or water and sprinkle with cinnamon sugar.', 'Bake 40 to 45 minutes until deep golden and 88°C inside. Cover with foil if browning too quickly.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cinnamon-raisin-bread-recipe"}'::jsonb, false, null),
  (22, 'Classic Sandwich Bread', 'bread', 'easy', 12, 33, 12, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"milk","amount":113,"unit":"g"},{"name":"hot water","amount":130,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"}]'::jsonb, array['Mix everything and knead to a smooth, soft dough: by hand, with a stand mixer for 5 to 7 minutes, or on a bread machine''s dough cycle.', 'Rise 1 to 2 hours until puffy.', 'Deflate gently and shape into a 20 cm log.', 'Place in a greased tin and rise about 1 hour until domed 2.5 cm above the rim. Heat the oven to 175°C.', 'Bake 30 to 35 minutes until light golden and 88°C in the centre.', 'Cool on a rack before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-sandwich-bread-recipe"}'::jsonb, false, null),
  (23, 'Whole Grain Banana Bread', 'quick bread', 'easy', 10, 68, 10, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"ripe bananas, mashed","amount":454,"unit":"g"},{"name":"vegetable oil","amount":99,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":120,"unit":"g"},{"name":"whole wheat flour","amount":113,"unit":"g"},{"name":"baking soda","amount":4,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"chopped walnuts (optional)","amount":57,"unit":"g"},{"name":"sugar, for topping","amount":13,"unit":"g"},{"name":"ground cinnamon, for topping","amount":1.3,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease the tin.', 'Mix the bananas, oil, sugar, eggs and vanilla.', 'Add both flours, the baking soda and powder, salt, cinnamon and walnuts and mix until fully combined.', 'Pour into the tin and sprinkle with the topping sugar and cinnamon.', 'Bake 60 to 75 minutes until set and about 96°C in the centre. Tent with foil if it browns too fast.', 'Cool 15 minutes in the tin, then completely on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/whole-grain-banana-bread-recipe"}'::jsonb, false, null),
  (24, 'Whole Wheat Challah', 'bread', 'medium', 30, 30, 16, null, null, array['vegetarian']::text[], '[{"name":"water","amount":113,"unit":"g"},{"name":"vegetable oil","amount":74,"unit":"g"},{"name":"honey","amount":85,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"whole wheat pastry flour","amount":191,"unit":"g"},{"name":"bread flour","amount":240,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"instant yeast","amount":7.5,"unit":"g"}]'::jsonb, array['Mix and knead everything into a soft, smooth dough.', 'Cover and rise 1 to 2 hours until puffy and nearly doubled.', 'Line a baking tray. Deflate the dough, divide into three, shape into logs and rest 10 minutes.', 'Roll each into a 45 cm rope, braid and tuck the ends under.', 'Cover loosely and rise about 1 hour until puffy but not doubled. Heat the oven to 190°C.', 'Bake 20 minutes, tent with foil, then bake 10 more until deep golden and 88°C inside.', 'Cool to lukewarm on a rack before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/millies-whole-wheat-challah-recipe"}'::jsonb, false, null),
  (25, 'Golden Vanilla Pound Cake', 'cake', 'easy', 10, 65, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"butter","amount":170,"unit":"g"},{"name":"cream cheese","amount":85,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"almond extract","amount":4,"unit":"g"},{"name":"eggs","amount":5,"unit":"count"},{"name":"milk","amount":43,"unit":"g"},{"name":"all-purpose flour","amount":226,"unit":"g"},{"name":"sugar, for the glaze","amount":25,"unit":"g"},{"name":"vanilla extract, for the glaze","amount":4,"unit":"g"},{"name":"water, for the glaze","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and lightly grease the tin.', 'Beat the butter, cream cheese, salt, sugar, baking powder and both extracts until smooth.', 'Add the eggs one at a time. After the last, beat on high for 3 minutes, then stir in the milk.', 'Mix in the flour on low speed until just combined and scrape into the tin.', 'Stir the glaze ingredients into a drizzly syrup.', 'Set the tin on a tray and bake 55 minutes, brush with the glaze, then bake 15 to 20 minutes more until a skewer comes out clean (about 95°C in the centre).', 'Cool 5 minutes, turn out and cool completely.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/golden-vanilla-pound-cake-recipe"}'::jsonb, false, null),
  (26, 'Lemon-Glazed Pound Cake', 'cake', 'medium', 20, 57, 16, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"butter","amount":198,"unit":"g"},{"name":"cream cheese","amount":85,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"all-purpose flour","amount":206,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"vanilla extract","amount":9,"unit":"g"},{"name":"lemon oil","amount":2.5,"unit":"g"},{"name":"eggs","amount":5,"unit":"count"},{"name":"lemon juice, for the glaze","amount":57,"unit":"g"},{"name":"sugar, for the glaze","amount":99,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease the tin or tins (two 21 cm loaves or one tube or bundt tin).', 'Beat the butter and cream cheese until fluffy. Add the salt, sugar, flour and baking powder and beat 5 minutes. The batter is stiff.', 'Mix in the vanilla and lemon oil, then the eggs one at a time, scraping the bowl each time. Spoon into the tin.', 'Bake 55 to 60 minutes for a tube tin, or 35 to 40 for loaves, until a skewer comes out clean.', 'Shortly before it is done, warm the lemon juice and sugar until the sugar dissolves. Do not boil.', 'Cool 10 minutes, turn out, then prick the warm cake all over and drizzle on the glaze in stages.', 'Cool several hours before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/lemon-glazed-pound-cake-recipe"}'::jsonb, false, null),
  (27, 'Quick and Easy Vanilla Cake with Chocolate Frosting', 'cake', 'easy', 20, 36, 8, 'round-20', null, array['vegetarian']::text[], '[{"name":"sugar","amount":198,"unit":"g"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"salt","amount":6,"unit":"g"},{"name":"vanilla extract","amount":10,"unit":"g"},{"name":"almond extract","amount":2,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"cornstarch","amount":28,"unit":"g"},{"name":"baking powder","amount":5,"unit":"g"},{"name":"icing sugar, for the frosting","amount":227,"unit":"g"},{"name":"butter, for the frosting","amount":57,"unit":"g"},{"name":"cocoa powder","amount":16,"unit":"g"},{"name":"vanilla extract, for the frosting","amount":4,"unit":"g"},{"name":"milk, for the frosting","amount":35,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C. Grease a 20 cm round tin and line it with parchment.', 'Whisk the sugar, oil, egg, salt and extracts hard for 1 minute until thick and pale.', 'Melt the butter into the warm milk and whisk it slowly into the egg mixture.', 'Sift in the flour, cornstarch and baking powder and whisk. The batter is thin and small lumps are fine.', 'Bake 34 to 38 minutes until the centre springs back and a skewer comes out clean.', 'Cool 15 minutes in the tin, then turn out and cool completely.', 'For the frosting, beat the icing sugar, soft butter, cocoa, vanilla and a pinch of salt on low until crumbly.', 'Add 2 tablespoons of milk and beat smooth, adding more if stiff. Spread over the cooled cake.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/quick-and-easy-vanilla-cake-recipe"}'::jsonb, false, null),
  (28, 'Chocolate Olive Oil Cake', 'cake', 'easy', 10, 26, 9, 'square-23', null, array['vegetarian']::text[], '[{"name":"cake flour","amount":210,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"black cocoa","amount":11,"unit":"g"},{"name":"cocoa powder","amount":11,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking soda","amount":3.5,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"cider vinegar","amount":14,"unit":"g"},{"name":"extra-virgin olive oil","amount":150,"unit":"g"},{"name":"water","amount":151,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"chocolate chips, for the topping","amount":57,"unit":"g"},{"name":"sugar, for the topping","amount":25,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 23 cm square tin.', 'Whisk the flour, sugar, both cocoas, salt and baking soda.', 'Whisk the vanilla, vinegar, oil, water and eggs in another bowl, then combine with the dry mix and pour into the tin.', 'Bake 24 to 28 minutes until a skewer comes out clean or with a few moist crumbs.', 'Meanwhile grind the topping chocolate finely and mix with the topping sugar.', 'As soon as the cake leaves the oven, scatter the chocolate mix over the top.', 'Return it to the oven for about 1 minute until the topping softens and settles.', 'Cool until cool to the touch, then chill 10 to 15 minutes until the topping sets.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/chocolate-olive-oil-cake-recipe"}'::jsonb, false, null),
  (29, 'Traditional Angel Food Cake', 'cake', 'hard', 20, 43, 16, null, null, array['vegetarian']::text[], '[{"name":"cake flour","amount":120,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"egg whites","amount":12,"unit":"count"},{"name":"salt","amount":3,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"cream of tartar","amount":4,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C. Do not grease the tube tin.', 'Whisk the flour with half of the sugar and set aside.', 'Beat the egg whites, salt and vanilla until frothy. Add the cream of tartar and beat to stiff, glossy peaks.', 'Beat in the remaining sugar a little at a time, then fold in the flour mixture gradually.', 'Spoon into the tin and bake 40 to 45 minutes until golden and the top springs back.', 'Turn the tin upside down over a bottle neck and cool for 1.5 hours.', 'Loosen the edges with a knife and ease the cake out.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/traditional-angel-food-cake-recipe"}'::jsonb, false, null),
  (30, 'Easy Cheesecake', 'cake', 'easy', 12, 30, 12, 'round-23', null, array['vegetarian']::text[], '[{"name":"graham cracker crumbs","amount":150,"unit":"g"},{"name":"icing sugar","amount":28,"unit":"g"},{"name":"butter, melted","amount":85,"unit":"g"},{"name":"salt","amount":1,"unit":"g"},{"name":"cream cheese","amount":452,"unit":"g"},{"name":"sugar","amount":133,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C.', 'Mix the crumbs, icing sugar, melted butter and salt until evenly combined.', 'Press into a 23 cm pie dish (at least 3 cm deep), keeping the base thicker than the sides.', 'Beat the cream cheese and sugar smooth on low-medium speed, then mix in the eggs and vanilla.', 'Pour over the crust and level.', 'Bake 20 minutes, shield the crust, then bake about 10 more until the filling is 74 to 77°C near the edge. The centre looks soft.', 'Cool on a rack, then chill covered until serving.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/easy-cheesecake-recipe"}'::jsonb, false, null),
  (31, 'Kitchen Sink Carrot Cake', 'cake', 'medium', 15, 45, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"eggs","amount":4,"unit":"count"},{"name":"sugar","amount":198,"unit":"g"},{"name":"light brown sugar","amount":159,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"butter, melted","amount":170,"unit":"g"},{"name":"vegetable oil","amount":149,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"ground nutmeg","amount":1.5,"unit":"g"},{"name":"ground allspice","amount":0.3,"unit":"g"},{"name":"carrots, finely grated","amount":347,"unit":"g"},{"name":"pecans or walnuts, chopped","amount":110,"unit":"g"},{"name":"unsweetened shredded coconut","amount":53,"unit":"g"},{"name":"dried pineapple, diced","amount":71,"unit":"g"},{"name":"butter, for the frosting","amount":85,"unit":"g"},{"name":"cream cheese","amount":227,"unit":"g"},{"name":"vanilla extract, for the frosting","amount":4,"unit":"g"},{"name":"icing sugar","amount":397,"unit":"g"},{"name":"milk","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 33 x 23 cm tin.', 'Beat the eggs, both sugars and the vanilla until smooth.', 'Stir the melted butter into the oil and stream it into the eggs while beating.', 'Whisk the flour, baking powder, baking soda, salt and spices, then stir into the wet mix until smooth.', 'Fold in the carrots, nuts, coconut and pineapple.', 'Spread to the edges and bake 40 to 50 minutes until golden and a skewer comes out clean. Cool completely in the tin.', 'Beat the soft butter, cream cheese and vanilla until fluffy, add the icing sugar gradually, then milk until spreadable.', 'Frost the cooled cake.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/kitchen-sink-carrot-cake-recipe"}'::jsonb, false, null),
  (32, 'Blueberry Muffins', 'muffins', 'easy', 20, 21, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":270,"unit":"g"},{"name":"baking powder","amount":7,"unit":"g"},{"name":"baking soda","amount":2.5,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"sugar","amount":160,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"sour cream or yogurt","amount":113,"unit":"g"},{"name":"blueberries","amount":213,"unit":"g"},{"name":"coarse sugar, for sprinkling","amount":12,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C. Line a 12-cup muffin tin with paper cases and grease them.', 'Whisk the flour, baking powder, baking soda and salt.', 'Beat the oil with the sugar until frothy, then beat in the eggs one at a time.', 'Mix in the vanilla and sour cream.', 'Add the dry ingredients on low speed until smooth. The batter is very thick.', 'Fold in the blueberries by hand.', 'Fill each cup generously, sprinkle with coarse sugar and bake 18 to 24 minutes until a skewer comes out clean. Move to a rack promptly.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/blueberry-muffins-recipe"}'::jsonb, false, null),
  (33, 'Bran Muffins', 'muffins', 'easy', 15, 26, 12, null, null, array['vegetarian']::text[], '[{"name":"boiling water","amount":113,"unit":"g"},{"name":"wheat bran, for soaking","amount":43,"unit":"g"},{"name":"vegetable oil","amount":67,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"raisins","amount":128,"unit":"g"},{"name":"buttermilk","amount":283,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"bran cereal","amount":128,"unit":"g"}]'::jsonb, array['Pour the boiling water over the wheat bran. When cool, stir in the oil and egg.', 'Whisk the flour, sugar, baking soda, baking powder and salt, then stir in the raisins.', 'Mix the buttermilk and brown sugar into the dry ingredients, then add the bran cereal and the soaked bran mixture.', 'Cover and refrigerate overnight.', 'Heat the oven to 190°C and line or grease a 12-cup muffin tin.', 'Stir the batter and fill each cup generously.', 'Bake 22 to 27 minutes until a skewer comes out clean. Cool 10 minutes in the tin, then remove.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/bran-muffins-recipe"}'::jsonb, false, null),
  (34, 'The Simplest Muffins', 'muffins', 'easy', 7, 17, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"quick-cooking oats","amount":45,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"ground cinnamon (optional)","amount":3,"unit":"g"},{"name":"dried fruit, nuts or chocolate chips","amount":170,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"}]'::jsonb, array['Heat the oven to 220°C and grease a 12-cup muffin tin or line it with greased papers.', 'Mix the flour, oats, sugar, salt, baking powder, cinnamon and add-ins in a bowl.', 'Whisk the milk, vanilla, melted butter and eggs in another bowl.', 'Combine the wet and dry just until blended.', 'Fill each cup about three-quarters full.', 'Bake 15 to 18 minutes until set and lightly golden.', 'Rest 5 minutes in the tin, then cool on a rack. Best warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/the-simplest-muffins-recipe"}'::jsonb, false, null),
  (35, 'Oat Muffins', 'muffins', 'easy', 20, 19, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"rolled oats","amount":45,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"butter, melted","amount":71,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"cinnamon sugar, for the top","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and grease a 12-cup muffin tin or line it with papers.', 'Whisk the flour, oats, sugar, salt and baking powder in a large bowl.', 'Beat the milk, melted butter, eggs and vanilla in another bowl.', 'Fold the wet into the dry until just combined.', 'Divide among the cups and sprinkle with cinnamon sugar.', 'Bake 18 to 20 minutes until golden and a skewer comes out clean.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/oat-muffins-recipe"}'::jsonb, false, null),
  (36, 'Lemon Poppy Seed Muffins', 'muffins', 'easy', 7, 19, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"yellow cornmeal","amount":46,"unit":"g"},{"name":"lemon juice powder","amount":21,"unit":"g"},{"name":"poppy seeds","amount":28,"unit":"g"},{"name":"baking powder","amount":9,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted","amount":113,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"icing sugar, for the glaze","amount":113,"unit":"g"},{"name":"lemon juice powder, for the glaze","amount":7,"unit":"g"},{"name":"milk, for the glaze","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and grease a 12-cup muffin tin or line it with papers.', 'Whisk the flour, sugar, cornmeal, lemon juice powder, poppy seeds, baking powder and salt.', 'Whisk the milk, eggs, melted butter and vanilla in another bowl.', 'Stir the wet into the dry just until moistened and fill the cups almost to the top.', 'Bake 18 to 20 minutes until a skewer comes out clean. Rest 5 minutes, then move to a rack.', 'Stir the glaze ingredients, adding sugar or milk until spreadable.', 'Spread over the warm muffins and let it set.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/lemon-poppy-seed-muffins-recipe"}'::jsonb, false, null),
  (37, 'Fudge Brownies', 'bars', 'easy', 12, 30, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"eggs","amount":4,"unit":"count"},{"name":"Dutch-process cocoa","amount":106,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"espresso powder (optional)","amount":2,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":447,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"chocolate chips","amount":340,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 33 x 23 cm tin (line with parchment so you can lift the brownies out).', 'Beat the eggs, cocoa, salt, baking powder, espresso powder and vanilla until thick and mostly smooth.', 'Melt the butter, stir in the sugar and warm to 45 to 50°C without bubbling. Partly dissolved sugar gives the shiny top.', 'Stir the warm butter and sugar into the egg mixture until smooth.', 'Fold in the flour and chocolate chips, scraping the bowl well.', 'Spread evenly in the tin and bake 28 to 32 minutes until the edges are set and a skewer shows moist crumbs, not raw batter.', 'Cool completely before cutting.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/fudge-brownies-recipe"}'::jsonb, false, null),
  (38, 'Deep-Dark Fudgy Brownies', 'bars', 'easy', 10, 38, 16, 'square-23', null, array['vegetarian']::text[], '[{"name":"Dutch-process cocoa","amount":57,"unit":"g"},{"name":"sugar","amount":298,"unit":"g"},{"name":"icing sugar","amount":57,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"all-purpose flour","amount":120,"unit":"g"},{"name":"espresso powder","amount":7,"unit":"g"},{"name":"toasted pecans or walnuts, chopped (optional)","amount":113,"unit":"g"},{"name":"semisweet chocolate chips (optional)","amount":170,"unit":"g"},{"name":"vegetable oil","amount":99,"unit":"g"},{"name":"water or brewed coffee","amount":28,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"}]'::jsonb, array['Heat the oven to 175°C and lightly grease a 23 cm square tin.', 'Whisk the cocoa, both sugars, salt, flour, espresso powder, and the nuts and chocolate chips if using.', 'Stir in the oil, water or coffee and eggs until combined.', 'Spread evenly in the tin.', 'Bake 33 to 35 minutes (40 to 45 in a 20 cm tin). They are done when the crumb looks moist and crumbly rather than shiny.', 'Cool on a rack for 1 hour before cutting.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/deep-dark-fudgy-brownies-recipe"}'::jsonb, false, null),
  (39, 'Brown Sugar Blondies', 'bars', 'easy', 20, 33, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"butter, melted","amount":113,"unit":"g"},{"name":"light brown sugar","amount":426,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"vanilla extract","amount":10,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"chopped pecans or walnuts","amount":168,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and lightly grease a 33 x 23 cm tin.', 'Stir the melted butter, brown sugar and salt until it looks like wet sand.', 'Beat in the cold eggs one at a time, then the vanilla.', 'Stir in the flour and baking powder until smooth with no dry streaks.', 'Fold in 113 g of the nuts.', 'Spread in the tin with a wet spatula and scatter the remaining nuts on top.', 'Bake 30 to 35 minutes until the top is shiny and a skewer shows moist crumbs. Cool completely before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/blondies-recipe"}'::jsonb, false, null),
  (40, 'Granola Brownie Bars', 'bars', 'easy', 20, 33, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"butter","amount":170,"unit":"g"},{"name":"light brown sugar","amount":373,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"whole wheat flour","amount":227,"unit":"g"},{"name":"baking powder","amount":10,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"granola and other mix-ins","amount":480,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Grease a 33 x 23 cm tin and line it with foil or parchment.', 'Beat the butter and sugar, then beat in the eggs one at a time and the vanilla.', 'Whisk the flour, baking powder and salt and mix into the butter mixture.', 'Stir in the granola and any other mix-ins and spread in the tin.', 'Bake 30 to 35 minutes until golden at the edges and set in the centre.', 'Cool on a rack. Lift out while lukewarm and cut once fully cool.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/granola-brownie-bars-recipe"}'::jsonb, false, null),
  (41, 'Buttermilk Biscuits', 'scones', 'easy', 20, 18, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"sugar","amount":12.5,"unit":"g"},{"name":"butter","amount":85,"unit":"g"},{"name":"buttermilk","amount":240,"unit":"g"},{"name":"milk, for brushing","amount":15,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C with a rack in the upper third. Line a tray with parchment.', 'Whisk the flour, salt, baking powder and sugar.', 'Cut in the butter until the mix looks like coarse breadcrumbs.', 'Add the buttermilk and mix briefly until cohesive. If dry, add up to 28 g more.', 'Pat into a 2 cm thick rectangle, fold in thirds, and pat back to 2 cm.', 'Cut with a 6 cm cutter, or into squares to avoid scraps.', 'Place on the tray, brush with milk and bake 15 to 20 minutes until lightly browned. Serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/buttermilk-biscuits-recipe"}'::jsonb, false, null),
  (42, 'Classic Buttermilk Scones', 'scones', 'easy', 10, 14, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"whole wheat flour","amount":113,"unit":"g"},{"name":"baking powder","amount":14,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"buttermilk","amount":227,"unit":"g"},{"name":"coarse sugar (optional)","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 260°C and line a tray with parchment.', 'Mix the flours, baking powder, baking soda, salt and sugar thoroughly.', 'Cut in the butter until crumbly. Add any extras now.', 'Stir in the buttermilk briefly until the dough is shaggy.', 'Knead about 10 times on a floured surface and shape into two 15 cm rounds about 1.5 cm thick.', 'Cut each into 6 wedges, pressing straight down.', 'Space on the tray, lower the oven to 230°C and bake 13 to 15 minutes until light golden. Serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-scones-recipe"}'::jsonb, false, null),
  (43, 'Cheddar and Scallion Scones', 'scones', 'easy', 10, 22, 10, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"cold butter, cubed","amount":85,"unit":"g"},{"name":"sharp cheddar, grated","amount":113,"unit":"g"},{"name":"scallions, chopped","amount":30,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"milk or sour cream","amount":74,"unit":"g"},{"name":"Dijon mustard (optional)","amount":14,"unit":"g"},{"name":"hot sauce (optional)","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and line a tray.', 'Mix the flour, salt and baking powder and rub in the butter until crumbly.', 'Fold in the cheese and scallions.', 'Whisk the eggs, milk, mustard and hot sauce and stir into the dry mix until just moistened. The dough is very sticky.', 'On a floured surface pat into a 25 x 5 cm rectangle.', 'Cut into 5 squares, then cut each in half diagonally to make 10 triangles.', 'Space 2.5 cm apart and bake 20 to 23 minutes until browned. Serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cheddar-cheese-and-scallion-scones-recipe"}'::jsonb, false, null),
  (44, 'Soft Dinner Rolls', 'buns', 'medium', 23, 21, 16, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":7,"unit":"g"},{"name":"sugar","amount":39,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"potato flour or dried potato flakes","amount":46,"unit":"g"},{"name":"water","amount":71,"unit":"g"},{"name":"milk","amount":170,"unit":"g"},{"name":"butter","amount":43,"unit":"g"},{"name":"butter, melted, for brushing","amount":14,"unit":"g"}]'::jsonb, array['Mix everything into a soft dough and knead 6 minutes in a mixer or 8 by hand, until smooth and bouncy.', 'Rise in a greased covered bowl 1 to 2 hours until doubled.', 'Deflate, divide into 16 pieces of about 45 g and shape into balls.', 'Place in a greased 33 x 23 cm tin, cover and rise about 1 hour until puffy and just touching. Heat the oven to 175°C near the end.', 'Bake 20 to 22 minutes until golden brown.', 'Brush with melted butter while warm and cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/soft-dinner-rolls-recipe"}'::jsonb, false, null),
  (45, 'Pillowy Cinnamon Rolls', 'buns', 'medium', 30, 16, 8, null, null, array['vegetarian']::text[], '[{"name":"milk, for the tangzhong","amount":113,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":24,"unit":"g"},{"name":"cold milk","amount":151,"unit":"g"},{"name":"bread flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"butter, melted, for the filling","amount":14,"unit":"g"},{"name":"light brown sugar","amount":107,"unit":"g"},{"name":"bread flour, for the filling","amount":14,"unit":"g"},{"name":"ground cinnamon","amount":9,"unit":"g"},{"name":"butter, melted, for brushing and icing","amount":42,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"icing sugar","amount":170,"unit":"g"},{"name":"milk, for the icing","amount":21,"unit":"g"}]'::jsonb, array['Cook the tangzhong milk and flour over medium heat until thick and paste-like. Scrape into a mixing bowl.', 'Add the dough ingredients in order. Mix, then knead 10 to 15 minutes until smooth, elastic and tacky.', 'Rise 1 to 1.5 hours until puffy.', 'Mix the filling ingredients to a damp-sand texture.', 'Roll the dough to a 25 x 30 cm rectangle about 1 cm thick. Spread the filling, leaving a 1 cm strip bare, roll into a log and cut into 8 pieces (dental floss cuts cleanly).', 'Space the rolls at least 5 cm apart on a lined tray, tuck the ends under and proof 30 to 60 minutes until puffy.', 'Heat the oven to 190°C. Bake 14 to 18 minutes until golden and 88°C in the centre. Brush with half the melted butter and cool 10 to 15 minutes.', 'Beat the rest of the butter with the vanilla, icing sugar and enough milk for a smooth icing. Ice and serve.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/perfectly-pillowy-cinnamon-rolls-recipe"}'::jsonb, false, null),
  (46, 'Easy Hot Cross Buns', 'buns', 'medium', 25, 20, 12, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"dried fruit","amount":78,"unit":"g"},{"name":"raisins or currants","amount":78,"unit":"g"},{"name":"apple juice or rum","amount":57,"unit":"g"},{"name":"milk","amount":283,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"butter","amount":85,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"ground cloves or allspice","amount":0.6,"unit":"g"},{"name":"ground nutmeg","amount":0.6,"unit":"g"},{"name":"salt","amount":11,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"all-purpose flour","amount":540,"unit":"g"},{"name":"egg white, for glazing","amount":1,"unit":"count"},{"name":"milk, for glazing","amount":14,"unit":"g"},{"name":"icing sugar","amount":128,"unit":"g"},{"name":"vanilla extract","amount":2.5,"unit":"g"},{"name":"milk, for the icing","amount":20,"unit":"g"}]'::jsonb, array['Warm the dried fruit with the juice or rum in the microwave, then cool to room temperature.', 'Mix the milk, eggs, yolk, butter, yeast, sugar, spices, salt, baking powder and flour and knead until soft. The dough is slack, so grease your hands. Mix in the fruit.', 'Rise covered 1 hour. It may not double.', 'Divide into 12 pieces of about 106 g, round them and set them in a greased tin.', 'Cover and rise about 1 hour until the buns touch. Heat the oven to 190°C.', 'Beat the egg white with the milk and brush over the buns.', 'Bake 20 minutes until golden, then turn out onto a rack.', 'Beat the icing ingredients to a thick pipeable icing and pipe a cross on each cooled bun.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/easy-hot-cross-buns-recipe"}'::jsonb, false, null),
  (47, 'English Muffins', 'buns', 'medium', 45, 25, 6, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the preferment","amount":190,"unit":"g"},{"name":"instant yeast","amount":2,"unit":"g"},{"name":"milk","amount":152,"unit":"g"},{"name":"water","amount":102,"unit":"g"},{"name":"all-purpose flour, for the dough","amount":120,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"butter, melted","amount":18,"unit":"g"},{"name":"cornmeal, for dusting","amount":25,"unit":"g"}]'::jsonb, array['Whisk the preferment flour, yeast, milk and water into a thick batter and rest 1 to 4 hours until bubbly and doubled.', 'Mix in the dough flour, salt, sugar and butter to a soft, sticky dough, then do 6 to 8 bowl folds.', 'Rest 1 hour, fold again, and rest another hour until very puffy.', 'Pat to 1 cm thick on cornmeal and cut six 9 cm rounds, re-pressing the scraps.', 'Rest the rounds on cornmeal-dusted parchment for 20 to 30 minutes.', 'Cook in a preheated skillet or griddle over medium-low heat, 10 to 15 minutes per side, until browned and about 2.5 cm thick.', 'Cool on a rack, split with a fork and toast.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/english-muffins-recipe"}'::jsonb, false, null),
  (48, 'Naan', 'flatbread', 'medium', 30, 14, 8, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"bread flour","amount":90,"unit":"g"},{"name":"warm water","amount":142,"unit":"g"},{"name":"full-fat plain Greek yogurt","amount":71,"unit":"g"},{"name":"ghee or butter, melted","amount":28,"unit":"g"},{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"ghee or butter, melted, for brushing","amount":28,"unit":"g"},{"name":"nigella seeds (optional)","amount":4,"unit":"g"},{"name":"fresh cilantro, chopped (optional)","amount":4,"unit":"g"}]'::jsonb, array['Mix the dough ingredients into a shaggy mass, then knead until smooth, bouncy and slightly tacky.', 'Cover and rise in a greased bowl until doubled, 50 to 60 minutes.', 'Divide into 8 pieces of about 65 g, shape into balls, cover and rest 20 minutes.', 'Heat a cast-iron pan or griddle over medium-high heat.', 'Roll or stretch each ball to a 15 cm round or 18 cm oval for thicker naan, or larger for thinner.', 'Cook 30 to 40 seconds until bubbles form and the underside browns, flip and cook 40 to 50 seconds more.', 'Brush with melted ghee, add seeds and cilantro if using, and keep warm in foil or a 95°C oven.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/naan-recipe"}'::jsonb, false, null),
  (49, 'Big Batch Quick Dinner Rolls', 'buns', 'easy', 25, 22, 24, null, null, array['vegetarian']::text[], '[{"name":"water","amount":113,"unit":"g"},{"name":"milk","amount":454,"unit":"g"},{"name":"butter","amount":43,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"salt","amount":18,"unit":"g"},{"name":"instant yeast","amount":23,"unit":"g"},{"name":"all-purpose flour","amount":780,"unit":"g"}]'::jsonb, array['Stir the water, milk, butter, sugar, salt and yeast together and rest 6 to 8 minutes until foamy.', 'Mix in 600 g of the flour until shaggy. Add the rest gradually until the dough is smooth and slightly tacky. Knead 10 minutes by hand or 4 to 5 by machine.', 'Cover and rise 20 minutes until puffy.', 'Deflate, pat into a 20 x 30 cm rectangle, cut into 24 pieces and shape into tight balls.', 'Arrange in greased or lined tins.', 'Cover and rise 20 to 25 minutes. Heat the oven to 175°C.', 'Bake 20 to 25 minutes until golden and 88°C inside. Brush with melted butter and serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/big-batch-quick-dinner-rolls-recipe"}'::jsonb, false, null),
  (50, 'Classic Apple Pie', 'pie', 'medium', 45, 60, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the crust","amount":300,"unit":"g"},{"name":"salt, for the crust","amount":4.5,"unit":"g"},{"name":"vegetable shortening","amount":60,"unit":"g"},{"name":"cold butter","amount":113,"unit":"g"},{"name":"ice water","amount":120,"unit":"g"},{"name":"apples, peeled and sliced","amount":904,"unit":"g"},{"name":"lemon juice","amount":28,"unit":"g"},{"name":"sugar","amount":149,"unit":"g"},{"name":"all-purpose flour, for the filling","amount":14,"unit":"g"},{"name":"cornstarch","amount":14,"unit":"g"},{"name":"salt, for the filling","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"ground nutmeg","amount":0.7,"unit":"g"},{"name":"ground allspice","amount":0.7,"unit":"g"},{"name":"boiled cider or apple juice concentrate (optional)","amount":85,"unit":"g"},{"name":"vanilla extract (optional)","amount":8,"unit":"g"},{"name":"butter, diced","amount":28,"unit":"g"},{"name":"egg white, for glazing","amount":1,"unit":"count"},{"name":"coarse sugar, for sprinkling","amount":10,"unit":"g"}]'::jsonb, array['Mix the crust flour and salt, cut in the shortening and butter to dime-sized flakes, and add ice water until the dough holds. Divide into two disks and chill 30 minutes.', 'Heat the oven to 220°C and grease a 23 cm pie dish at least 4 cm deep.', 'Toss the apples with the lemon juice. Whisk the sugar, filling flour, cornstarch, salt and spices, coat the apples, then stir in the cider and vanilla.', 'Roll one disk to a 30 cm round and fit it into the dish, leaving a 2.5 cm overhang.', 'Fill, dot with the diced butter and cover with the second rolled disk. Seal, crimp and cut steam vents.', 'Chill the assembled pie 10 minutes while the oven finishes heating.', 'Brush with beaten egg white and sprinkle with coarse sugar. Bake 20 minutes at 220°C, then 40 minutes at 190°C until the filling bubbles. Shield the edges if they brown too fast.', 'Cool completely before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/apple-pie-recipe"}'::jsonb, false, null),
  (51, 'Pumpkin Pie', 'pie', 'medium', 30, 48, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"sugar","amount":99,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"all-purpose flour","amount":8,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground ginger","amount":2,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"ground nutmeg","amount":1.2,"unit":"g"},{"name":"ground cloves","amount":0.3,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"pumpkin purée","amount":425,"unit":"g"},{"name":"light cream or evaporated milk","amount":283,"unit":"g"},{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"}]'::jsonb, array['Heat the oven to 200°C.', 'Whisk the sugars, flour, salt and spices in a large bowl.', 'Beat the eggs, pumpkin and cream together, then whisk into the dry mix. For deeper flavour, cover and chill overnight.', 'Roll the crust to a 33 cm round, fit it into a greased 23 cm dish and crimp above the rim. Chill while the oven heats.', 'Set the dish on a baking tray and pour in the filling.', 'Bake 45 to 50 minutes until the edges are set 5 cm in and the centre still wobbles.', 'Cool on a rack. The centre finishes setting as it rests. Refrigerate leftovers.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/pumpkin-pie-recipe"}'::jsonb, false, null),
  (52, 'Old-Fashioned Pecan Pie', 'pie', 'medium', 30, 48, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"butter","amount":113,"unit":"g"},{"name":"all-purpose flour","amount":30,"unit":"g"},{"name":"light brown sugar","amount":454,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"milk","amount":85,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"cider vinegar","amount":10,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"pecans, diced","amount":57,"unit":"g"},{"name":"pecan halves, for the top","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C.', 'Roll out the crust, fit it into a greased 23 cm dish and crimp the edge.', 'Melt the butter and let it cool.', 'Mix the flour, sugar and salt in a large bowl, then beat in the milk and eggs.', 'Stir in the vinegar, vanilla, cooled butter and diced pecans (toast them first at 175°C for 6 to 8 minutes for deeper flavour).', 'Pour into the crust and arrange the pecan halves on top.', 'Bake 47 to 50 minutes until puffed and set with the centre barely wobbling.', 'Cool completely before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/old-fashioned-pecan-pie-recipe"}'::jsonb, false, null),
  (53, 'Classic Lemon Meringue Pie', 'pie', 'hard', 25, 22, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":163,"unit":"g"},{"name":"salt, for the crust","amount":2,"unit":"g"},{"name":"vegetable oil","amount":67,"unit":"g"},{"name":"cold milk","amount":43,"unit":"g"},{"name":"sugar, for the filling","amount":298,"unit":"g"},{"name":"cornstarch","amount":43,"unit":"g"},{"name":"cold water","amount":340,"unit":"g"},{"name":"egg yolks","amount":3,"unit":"count"},{"name":"butter","amount":43,"unit":"g"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"lemon juice","amount":113,"unit":"g"},{"name":"vanilla extract, for the filling","amount":2,"unit":"g"},{"name":"egg whites","amount":3,"unit":"count"},{"name":"cream of tartar","amount":1,"unit":"g"},{"name":"sugar, for the meringue","amount":67,"unit":"g"},{"name":"vanilla extract, for the meringue","amount":5,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C. Mix the flour and salt, then stir in the oil and milk until a dough forms.', 'Roll to a 30 cm round between sheets of plastic or parchment, fit into a 23 cm pie dish, crimp and prick the base.', 'Bake the crust 12 to 15 minutes until just beginning to brown, then lower the oven to 200°C.', 'Cook the filling sugar, cornstarch and water over medium heat until thick and boiling. Boil 1 minute.', 'Whisk about a cup of the hot mix into the yolks, return it all to the pan and boil 1 minute until very thick.', 'Off the heat, stir in the butter, zest, lemon juice and vanilla. Pour into the crust.', 'Beat the egg whites with the cream of tartar, add the sugar gradually, and beat to stiff peaks. Beat in the vanilla.', 'Spread the meringue over the hot filling, sealing it to the crust. Bake 8 to 10 minutes until golden, then cool several hours.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-lemon-meringue-pie-recipe"}'::jsonb, false, null),
  (54, 'Classic Apple Crisp', 'pie', 'easy', 15, 60, 9, 'square-23', null, array['vegetarian']::text[], '[{"name":"apples, peeled and sliced","amount":907,"unit":"g"},{"name":"apple cider or lemon juice","amount":28,"unit":"g"},{"name":"light brown sugar, for the filling","amount":106,"unit":"g"},{"name":"butter, melted","amount":28,"unit":"g"},{"name":"apple pie spice","amount":3,"unit":"g"},{"name":"all-purpose flour, for the filling","amount":20,"unit":"g"},{"name":"salt, for the filling","amount":1.5,"unit":"g"},{"name":"all-purpose flour, for the topping","amount":90,"unit":"g"},{"name":"quick oats","amount":45,"unit":"g"},{"name":"salt, for the topping","amount":1.5,"unit":"g"},{"name":"light brown sugar, for the topping","amount":142,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"baking powder","amount":3,"unit":"g"},{"name":"cold butter","amount":113,"unit":"g"},{"name":"pecans or walnuts, diced (optional)","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 23 cm square dish.', 'Slice the apples about 6 mm thick, toss with the cider, brown sugar, melted butter, spice, flour and salt, and spread in the dish.', 'Whisk the topping flour, oats, salt, sugar, cinnamon and baking powder.', 'Work in the cold butter until crumbly, then mix in the nuts.', 'Spread the topping evenly over the apples and set the dish on a lined tray to catch drips.', 'Bake about 60 minutes until bubbling and golden on top.', 'Cool at least 20 minutes. It firms up as it cools.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-apple-crisp-recipe"}'::jsonb, false, null),
  (55, 'Cream Puffs and Éclairs', 'pastry', 'hard', 20, 45, 12, null, null, array['vegetarian']::text[], '[{"name":"water","amount":227,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"salt","amount":2,"unit":"g"},{"name":"all-purpose flour","amount":150,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"heavy cream, for the filling","amount":454,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"semisweet chocolate chips, for the icing","amount":170,"unit":"g"},{"name":"heavy cream, for the icing","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C and line two trays.', 'Boil the water, butter and salt until the butter melts.', 'Off the heat, add the flour all at once and stir hard. Return to medium heat and stir until the dough smooths and pulls from the pan, under a minute.', 'Cool 5 to 10 minutes, then beat in the eggs one at a time and beat at least 2 minutes more.', 'Spoon mounds for puffs, or pipe 13 cm logs for éclairs, about 8 cm apart.', 'Bake 15 minutes at 220°C, then 25 minutes at 175°C. Slit the tops and bake 5 minutes more to release steam. Cool, then split.', 'Whip the cream with the sugar and vanilla to stiff peaks and fill the puffs. (For éclairs, use pastry cream.)', 'Melt the chocolate in the hot cream, stir smooth and spread over éclairs.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cream-puffs-and-eclairs-recipe"}'::jsonb, false, null),
  (56, 'Quiche Lorraine', 'pie', 'medium', 35, 55, 8, 'round-23', null, array[]::text[], '[{"name":"single 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"bacon, chopped","amount":170,"unit":"g"},{"name":"onion, diced","amount":227,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"heavy cream","amount":227,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"black pepper","amount":0.6,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"chives or scallion tops","amount":6,"unit":"g"},{"name":"Swiss, Gruyère or cheddar, grated","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 220°C and lightly grease a 23 cm pie dish.', 'Fit the pastry into the dish, crimp the edge and prick the base.', 'Line with foil or parchment, fill with weights and pre-bake 15 minutes. Cool briefly, then remove the weights. Lower the oven to 175°C.', 'Brown the bacon, drain most of the fat, then soften the onion in the pan. Set aside.', 'Heat the milk, cream, salt and pepper to just below a simmer.', 'Whisk the eggs, whisk in a little hot cream to temper them, then stir back into the pan.', 'Spread the bacon and onion in the crust, pour in the custard and top with the chives and cheese.', 'Bake on a tray 35 to 40 minutes until a knife 5 cm from the edge comes out clean and the centre is 71 to 74°C. Cool 15 minutes.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/quiche-lorraine-recipe"}'::jsonb, false, null),
  (57, 'All-Butter Pie Crust', 'pie', 'easy', 15, 0, 16, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"buttermilk powder (optional)","amount":18,"unit":"g"},{"name":"cold unsalted butter","amount":227,"unit":"g"},{"name":"ice water","amount":128,"unit":"g"}]'::jsonb, array['Whisk the flour, salt and buttermilk powder.', 'Work in the cold cubed butter, leaving pea-sized pieces.', 'Add ice water a little at a time, tossing, until the dough holds together when squeezed.', 'Divide into two disks. Chill at least 30 minutes, or roll right away.', 'If chilled longer than 30 minutes, rest 10 to 15 minutes at room temperature until it rolls easily.', 'Use in a pie recipe (this makes two single crusts or one double crust). It keeps 2 days chilled or 2 months frozen, well wrapped.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/all-butter-pie-crust-recipe"}'::jsonb, false, null),
  (58, 'Custard Pie', 'pie', 'medium', 15, 65, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"salt, for the crust","amount":1.5,"unit":"g"},{"name":"baking powder","amount":1,"unit":"g"},{"name":"vegetable shortening","amount":43,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"vinegar","amount":4,"unit":"g"},{"name":"ice water","amount":57,"unit":"g"},{"name":"milk","amount":340,"unit":"g"},{"name":"cream","amount":227,"unit":"g"},{"name":"salt, for the filling","amount":1.5,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"sugar","amount":131,"unit":"g"},{"name":"vanilla extract","amount":14,"unit":"g"},{"name":"ground nutmeg","amount":0.7,"unit":"g"}]'::jsonb, array['Whisk the crust dry ingredients, cut in the shortening, then work in the butter, leaving some chunks.', 'Toss in the vinegar and ice water until the dough just holds, keeping visible bits of fat. Flatten, wrap and chill at least 30 minutes.', 'Roll to a 33 cm round, fit into a greased 23 cm dish, crimp the edge upright and chill while the oven heats to 190°C.', 'Blind bake with weights for 20 minutes, remove them and bake 10 to 15 minutes more until golden. Cool and lower the oven to 150°C.', 'Heat the milk, cream and salt until bubbles form at the edges and steam rises.', 'Whisk the eggs and sugar, temper with a quarter of the hot dairy, combine, strain and stir in the vanilla.', 'Pour into the crust, dust with nutmeg and shield the edges with foil.', 'Bake 35 to 40 minutes until set at the edges but wobbly in the centre (77 to 82°C inside). Cool, then refrigerate.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/custard-pie-recipe"}'::jsonb, false, null),
  (59, 'Strawberry Lemonade Bars', 'bars', 'easy', 20, 30, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"sugar","amount":264,"unit":"g"},{"name":"lemon zest","amount":6,"unit":"g"},{"name":"salt, for the bars","amount":6,"unit":"g"},{"name":"vanilla extract, for the bars","amount":4,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"lemon juice","amount":28,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"freeze-dried strawberries","amount":10,"unit":"g"},{"name":"butter, softened, for the frosting","amount":85,"unit":"g"},{"name":"salt, for the frosting","amount":0.7,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"vanilla extract, for the frosting","amount":4,"unit":"g"},{"name":"milk","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 20 cm metal square tin with a parchment sling and grease lightly.', 'Combine the sugar, zest, salt and vanilla in a bowl.', 'Melt the butter with the lemon juice and pour over the sugar mix. Whisk, then beat 30 seconds until thick and glossy. Whisk in the eggs.', 'Fold in the flour and baking powder until no streaks remain.', 'Spread in the tin and bake 28 to 32 minutes until set and golden with a few moist crumbs on a skewer.', 'Cool completely in the tin, about 1 hour.', 'Crush the strawberries to a fine powder. Beat the soft butter, strawberry powder and salt, add the icing sugar, vanilla and milk and whip until fluffy.', 'Spread over the bars and slice.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/strawberry-lemonade-bars-recipe"}'::jsonb, false, null),
  (60, 'Hot Buttered Soft Pretzels', 'buns', 'medium', 20, 9, 8, null, null, array['vegetarian']::text[], '[{"name":"bread flour","amount":300,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":4,"unit":"g"},{"name":"instant yeast","amount":7,"unit":"g"},{"name":"warm water","amount":212,"unit":"g"},{"name":"baking soda, for the bath","amount":28,"unit":"g"},{"name":"coarse pretzel salt","amount":3,"unit":"g"},{"name":"butter, melted","amount":43,"unit":"g"}]'::jsonb, array['Mix the flour, salt, sugar, yeast and warm water and knead 5 to 8 minutes by hand or mixer.', 'Put in a greased bowl, cover and rise 30 minutes.', 'Dissolve the baking soda in 227 g of boiling water and let it cool to lukewarm. Heat the oven to 245°C and prepare a tray.', 'Divide the dough into 8 pieces of about 70 g and rest uncovered 5 minutes.', 'Roll each into a 70 cm rope and twist into a pretzel.', 'Dip them in the soda bath four at a time for 2 minutes each, set them on the tray, salt lightly and rest 10 minutes.', 'Bake 8 to 9 minutes until golden.', 'Brush the warm pretzels generously with melted butter.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/hot-buttered-soft-pretzels-recipe"}'::jsonb, false, null),
  (61, 'Autumn Apple Turnovers', 'pastry', 'medium', 40, 25, 8, null, null, array['vegetarian']::text[], '[{"name":"pastry flour","amount":106,"unit":"g"},{"name":"all-purpose flour","amount":120,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"cold butter","amount":142,"unit":"g"},{"name":"ice water","amount":95,"unit":"g"},{"name":"apples, peeled and diced","amount":212,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"apple pie spice","amount":1,"unit":"g"},{"name":"boiled cider","amount":15,"unit":"g"},{"name":"pie filling enhancer","amount":14,"unit":"g"},{"name":"egg, for glazing","amount":1,"unit":"count"},{"name":"water, for glazing","amount":15,"unit":"g"}]'::jsonb, array['Whisk the flours and salt and cut in the cold butter to coarse crumbs.', 'Add the ice water gradually, fluffing with a fork, until the dough holds when squeezed. Fold it 3 to 4 times on parchment to make layers.', 'Pat into a rectangle, wrap and chill 30 minutes.', 'Stir the apples, sugar, spice, boiled cider, filling enhancer and a pinch of salt together.', 'Heat the oven to 220°C. Roll the dough to 23 x 43 cm, then trim to 20 x 40 cm.', 'Cut into eight 10 cm squares. Put 2 tablespoons of filling on each, moisten two edges, fold into triangles and seal.', 'Beat the egg with the water and brush over the tops.', 'Bake 25 to 30 minutes until golden and cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/autumn-apple-turnovers-recipe"}'::jsonb, false, null),
  (62, 'Apple Pecan Galette', 'pie', 'medium', 25, 25, 8, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the crust","amount":120,"unit":"g"},{"name":"semolina flour","amount":82,"unit":"g"},{"name":"sugar","amount":8,"unit":"g"},{"name":"salt, for the crust","amount":3,"unit":"g"},{"name":"cold butter","amount":113,"unit":"g"},{"name":"cold buttermilk","amount":70,"unit":"g"},{"name":"all-purpose flour, for the filling","amount":8,"unit":"g"},{"name":"salt, for the filling","amount":1.5,"unit":"g"},{"name":"pecans, toasted and diced","amount":57,"unit":"g"},{"name":"firm baking apples, sliced","amount":510,"unit":"g"},{"name":"light brown sugar","amount":40,"unit":"g"},{"name":"butter, diced","amount":28,"unit":"g"},{"name":"egg, for glazing","amount":1,"unit":"count"},{"name":"water, for glazing","amount":15,"unit":"g"},{"name":"coarse sparkling sugar","amount":10,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and line a tray with parchment.', 'Mix the flours, sugar and salt, cut in the cold butter to pea-sized pieces, then add the buttermilk gradually with a fork. Shape into a disk and chill at least 1 hour.', 'Roll to a 33 cm round, about 6 mm thick, and set on the tray.', 'Sprinkle the filling flour and salt over the dough, leaving a 2.5 cm border, then spread the pecans in a 23 cm circle in the centre.', 'Arrange the apples in concentric rings over the nuts and sprinkle with the brown sugar.', 'Fold the border up over the apples, leaving the centre open, and dot with the diced butter.', 'Brush the crust with the egg beaten with water and sprinkle with sparkling sugar.', 'Bake about 25 minutes until deep golden and cool until lukewarm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/apple-galette-recipe"}'::jsonb, false, null),
  (63, 'Red Velvet Cake', 'cake', 'medium', 45, 28, 12, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":266,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"red food colouring","amount":28,"unit":"g"},{"name":"Dutch-process cocoa","amount":14,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"baking soda","amount":4,"unit":"g"},{"name":"cider vinegar","amount":5,"unit":"g"},{"name":"all-purpose flour","amount":270,"unit":"g"},{"name":"buttermilk","amount":227,"unit":"g"},{"name":"butter, for the frosting","amount":113,"unit":"g"},{"name":"vegetable shortening","amount":92,"unit":"g"},{"name":"salt, for the frosting","amount":1.5,"unit":"g"},{"name":"meringue powder (optional)","amount":14,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"icing sugar","amount":681,"unit":"g"},{"name":"milk","amount":43,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Grease two 20 cm round tins, line the bases with parchment and grease the parchment.', 'Cream the butter and sugar, then beat in the eggs one at a time.', 'Mix in the red colouring, cocoa, salt, baking soda and vinegar.', 'Add the flour and buttermilk alternately, starting and ending with flour, keeping the batter smooth.', 'Spread the stiff batter into the tins and bake 25 to 30 minutes until set and a skewer comes out clean. Cool 10 minutes, then turn out.', 'For the frosting, beat the butter and shortening until fluffy, then add the salt, meringue powder and vanilla. Beat in the icing sugar and milk until smooth.', 'Slice each cake in half horizontally to make four layers. Frost between the layers and on top only, leaving the sides bare.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/red-velvet-cake-recipe"}'::jsonb, false, null),
  (64, 'Sour Cream Coffee Cake', 'cake', 'easy', 15, 35, 12, 'square-23', null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"sour cream or plain yogurt","amount":227,"unit":"g"},{"name":"sugar, for the filling","amount":99,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"chopped walnuts or pecans (optional)","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease and flour a 23 cm square tin.', 'Beat the butter, sugar and eggs until combined.', 'Whisk the flour, baking powder, baking soda and salt in another bowl.', 'Add the dry mix and the sour cream to the butter mixture in alternating portions, mixing after each.', 'Stir the filling sugar, cinnamon, vanilla and nuts together until crumbly.', 'Spread half the batter in the tin, sprinkle with half the filling, then repeat.', 'Bake 30 to 40 minutes until a skewer shows only a few moist crumbs. Serve warm or at room temperature.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/our-favorite-sour-cream-coffee-cake-recipe"}'::jsonb, false, null),
  (65, 'Chocolate Cake', 'cake', 'easy', 20, 34, 20, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":270,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"baking soda","amount":3,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"cocoa powder","amount":64,"unit":"g"},{"name":"sugar","amount":354,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"vegetable oil","amount":64,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"milk","amount":227,"unit":"g"},{"name":"brewed coffee or water","amount":113,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"}]'::jsonb, array['Heat the oven to 175°C and grease and flour a 33 x 23 cm tin.', 'Sift the flour, baking powder, baking soda, salt, cocoa and sugar into a bowl.', 'Beat in the soft butter on low for 1 minute, then add the oil until the mix looks sandy.', 'Combine the vanilla, milk and coffee, add to the dry mix and beat in two stages.', 'Add the eggs one at a time, beating well after each. The batter is thin.', 'Pour into the tin and bake about 34 minutes until the top springs back and a skewer comes out clean.', 'Cool completely in the tin, then frost with a chocolate frosting of your choice.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/chocolate-cake-recipe"}'::jsonb, false, null),
  (66, 'Streusel Lemon Coffee Cake', 'cake', 'easy', 15, 35, 16, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"all-purpose flour, for the streusel","amount":90,"unit":"g"},{"name":"ground cinnamon, for the streusel","amount":0.6,"unit":"g"},{"name":"lemon juice powder, for the streusel","amount":7,"unit":"g"},{"name":"salt, for the streusel","amount":1.5,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"cold butter","amount":85,"unit":"g"},{"name":"lemon zest","amount":3,"unit":"g"},{"name":"pecans, chopped","amount":85,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"lemon juice powder","amount":18,"unit":"g"},{"name":"ground cinnamon","amount":2,"unit":"g"},{"name":"butter, softened","amount":113,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"sour cream or plain yogurt","amount":227,"unit":"g"},{"name":"lemon juice, for the glaze","amount":14,"unit":"g"},{"name":"icing sugar, for the glaze","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 33 x 23 cm tin.', 'Mix the streusel flour, cinnamon, lemon powder, salt and brown sugar, cut in the cold butter until crumbly, then stir in the zest and pecans.', 'Sift the cake flour, baking powder, salt, lemon powder and cinnamon.', 'Cream the butter and sugar, then beat in the eggs one at a time.', 'Add half the dry mix, the sour cream, then the rest of the dry mix, stirring just until combined.', 'Spread in the tin, scatter on the streusel and bake 33 to 38 minutes until a knife comes out clean.', 'Cool 10 minutes in the tin. Whisk the glaze ingredients, drizzle over the cooled cake and serve at room temperature.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/streusely-lemon-coffee-cake-recipe"}'::jsonb, false, null),
  (67, 'Favorite Fudge Cake', 'cake', 'easy', 20, 30, 20, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"cold butter","amount":227,"unit":"g"},{"name":"cocoa powder","amount":42,"unit":"g"},{"name":"hot water","amount":227,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"sugar","amount":397,"unit":"g"},{"name":"baking soda","amount":4,"unit":"g"},{"name":"salt","amount":4,"unit":"g"},{"name":"buttermilk","amount":113,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"butter, for the frosting","amount":113,"unit":"g"},{"name":"cocoa powder, for the frosting","amount":21,"unit":"g"},{"name":"buttermilk, for the frosting","amount":85,"unit":"g"},{"name":"icing sugar","amount":454,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease and flour a 33 x 23 cm tin.', 'Melt the butter, then stir in the cocoa and hot water.', 'Whisk the flour, sugar, baking soda and salt in a large bowl.', 'Pour the cocoa mixture over the dry ingredients and stir. Beat in the buttermilk, eggs and vanilla and pour into the tin.', 'Bake about 30 minutes until a skewer comes out clean, then cool on a rack.', 'For the frosting, melt the butter in a pan and stir in the cocoa and buttermilk. Bring to the boil, remove from the heat and beat in the icing sugar until smooth.', 'Pour the warm frosting over the cake and serve from the tin.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/king-arthurs-favorite-fudge-cake-recipe"}'::jsonb, false, null),
  (68, 'Simple and Rich Chocolate Cake', 'cake', 'easy', 10, 35, 12, null, null, array['vegetarian']::text[], '[{"name":"cake flour","amount":270,"unit":"g"},{"name":"sugar","amount":397,"unit":"g"},{"name":"Dutch-process cocoa","amount":64,"unit":"g"},{"name":"baking powder","amount":9,"unit":"g"},{"name":"baking soda","amount":2.5,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"eggs","amount":4,"unit":"count"},{"name":"vegetable oil","amount":149,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"brewed coffee, cooled, or water","amount":283,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C with a rack in the centre. Grease two 20 or 23 cm round tins (or one 33 x 23 cm tin), or line muffin tins.', 'Whisk the flour, sugar, cocoa, baking powder, baking soda and salt.', 'Whisk the eggs, oil, vanilla and coffee or water.', 'Combine the wet and dry ingredients until smooth.', 'Divide the batter among the tins.', 'Bake until a skewer comes out clean and the centre springs back: about 22 minutes for rounds or cupcakes, longer for a large tin.', 'Cool fully in the tin before removing (cupcakes: 5 minutes, then a rack).']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/simple-and-rich-chocolate-cake-recipe"}'::jsonb, false, null),
  (69, 'Lemonade Cake', 'cake', 'hard', 35, 34, 12, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":347,"unit":"g"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"vanilla extract","amount":9,"unit":"g"},{"name":"lemon juice powder","amount":30,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"egg whites","amount":4,"unit":"count"},{"name":"cake flour","amount":360,"unit":"g"},{"name":"milk or plain yogurt","amount":284,"unit":"g"},{"name":"granulated sugar, for the frosting","amount":149,"unit":"g"},{"name":"boiling water","amount":113,"unit":"g"},{"name":"meringue powder","amount":43,"unit":"g"},{"name":"icing sugar","amount":454,"unit":"g"},{"name":"butter, for the frosting","amount":454,"unit":"g"},{"name":"lemon juice powder, for the frosting","amount":18,"unit":"g"},{"name":"lemon oil","amount":1,"unit":"g"},{"name":"salt, for the frosting","amount":1.5,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C and prepare two 23 cm round tins.', 'Cream the butter, sugar and oil for 2 to 3 minutes.', 'Beat in the baking powder, salt, vanilla and lemon juice powder.', 'Add the whole egg and egg whites gradually, scraping the bowl, until fluffy.', 'Add the flour in three portions alternating with the milk or yogurt.', 'Divide between the tins and bake 30 to 35 minutes until a skewer comes out clean. Cool 10 minutes in the tins, then fully on a rack.', 'For the frosting, dissolve the granulated sugar in the boiling water and cool. Whip with the meringue powder to soft peaks, add the icing sugar, then the butter, lemon powder, lemon oil and salt.', 'Frost between the layers and over the cake.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/lemonade-cake-recipe"}'::jsonb, false, null),
  (70, 'Cinnamon Roll Cake', 'cake', 'easy', 25, 33, 8, 'round-20', null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":53,"unit":"g"},{"name":"butter, softened, for the topping","amount":42,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"all-purpose flour","amount":160,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"plain whole-milk yogurt (not Greek)","amount":151,"unit":"g"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"icing sugar","amount":113,"unit":"g"},{"name":"cream cheese","amount":85,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C. Line a 20 cm round tin with parchment and grease the parchment and sides.', 'Mix the brown sugar, soft butter and cinnamon until smooth and slightly fluffy.', 'Whisk the flour, sugar, baking powder and salt.', 'Whisk in the yogurt, melted butter, egg and vanilla until mostly smooth. Small lumps are fine.', 'Spread the batter in the tin, dollop on the cinnamon topping (keep 1 to 2 teaspoons back) and swirl with a knife.', 'Bake 30 to 35 minutes until a skewer in the centre comes out clean. Cool 20 minutes in the tin.', 'Beat the icing sugar and cream cheese smooth, spread over the cake, drizzle with the reserved topping and swirl.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/cinnamon-roll-cake-recipe"}'::jsonb, false, null),
  (71, 'Our Favorite Chip Cookies', 'cookies', 'easy', 15, 15, 60, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":10,"unit":"g"},{"name":"rolled oats, ground to a coarse powder","amount":223,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"salt","amount":4,"unit":"g"},{"name":"chocolate chips","amount":454,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and grease or line two trays.', 'Cream the butter and both sugars, then beat in the eggs and vanilla.', 'Grind the oats to a coarse powder. Mix them in with the flour, baking powder, baking soda, salt and chocolate chips, gently.', 'Scoop tablespoon-sized balls onto the trays, 4 cm apart.', 'Bake 14 to 15 minutes until lightly browned. Cool on the trays.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/our-favorite-chip-cookies-recipe"}'::jsonb, false, null),
  (72, 'Classic Chocolate Chip Cookies', 'cookies', 'easy', 12, 12, 36, null, null, array['vegetarian']::text[], '[{"name":"light brown sugar","amount":142,"unit":"g"},{"name":"sugar","amount":131,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"vegetable shortening","amount":92,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"almond extract (optional)","amount":1,"unit":"g"},{"name":"cider vinegar","amount":5,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"semisweet chocolate chips","amount":340,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and grease or line two trays.', 'Beat both sugars, the butter, shortening, salt, extracts, vinegar and baking soda until smooth and creamy.', 'Beat in the egg and scrape the bowl well.', 'Mix in the flour, then the chocolate chips.', 'Scoop 3 cm balls, 5 cm apart, and add flaky salt on top if you like.', 'Bake 11 to 12 minutes until the edges are chestnut brown and the tops light golden.', 'Cool on the tray until firm enough to move.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-chocolate-chip-cookies-recipe"}'::jsonb, false, null),
  (73, 'Classic Cut-Out Cookies', 'cookies', 'medium', 30, 10, 30, null, null, array['vegetarian']::text[], '[{"name":"vegetable shortening","amount":91,"unit":"g"},{"name":"butter","amount":113,"unit":"g"},{"name":"light brown sugar","amount":107,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"vanilla extract","amount":9,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"cornstarch","amount":56,"unit":"g"}]'::jsonb, array['Beat the shortening, butter, both sugars, salt, baking powder and vanilla until blended.', 'Beat in the egg until fluffy.', 'Whisk the flour and cornstarch and mix into the butter mixture.', 'Halve the dough, shape into disks, wrap and chill 30 minutes.', 'Heat the oven to 175°C and grease or line two trays.', 'Roll one disk 3 mm thick on a floured surface and cut shapes. They spread very little, so place them close together.', 'Bake about 10 minutes until the edges barely brown, then cool on racks.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-cut-out-cookies-recipe"}'::jsonb, false, null),
  (74, 'Sugar Cookies', 'cookies', 'easy', 35, 11, 42, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"baking powder","amount":4,"unit":"g"},{"name":"baking soda","amount":1.5,"unit":"g"},{"name":"salt","amount":4.5,"unit":"g"},{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":248,"unit":"g"},{"name":"cream cheese","amount":57,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"almond extract","amount":1,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"sugar, for rolling","amount":149,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and grease or line two trays.', 'Whisk the flour, baking powder, baking soda and salt.', 'Cream the butter, sugar and cream cheese until light and fluffy.', 'Beat in the vanilla, almond extract and egg, scraping the bowl.', 'Mix in the dry ingredients on low just until combined.', 'Scoop tablespoon-sized portions, roll them in sugar, set 5 cm apart and flatten to 6 mm with a flat-bottomed glass.', 'Bake 10 to 12 minutes until the edges barely brown. Cool 5 minutes on the tray, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/sugar-cookies-recipe"}'::jsonb, false, null),
  (75, 'Oatmeal Cookies', 'cookies', 'easy', 12, 13, 15, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground nutmeg","amount":0.3,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"all-purpose flour","amount":90,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"rolled oats","amount":134,"unit":"g"},{"name":"raisins (optional)","amount":149,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line two trays with parchment.', 'Beat the butter, both sugars, cinnamon, vanilla, salt and nutmeg until smooth.', 'Beat in the egg until fully combined.', 'Mix in the flour and baking powder on low to a smooth dough.', 'Mix in the oats and raisins.', 'Scoop 36 g portions, 5 cm apart (flatten to 1 cm if they have raisins).', 'Bake one tray at a time for 12 to 14 minutes: less time for soft cookies, more for crisp. Cool on the tray.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/oatmeal-cookies-recipe"}'::jsonb, false, null),
  (76, 'Ranger Cookies', 'cookies', 'easy', 15, 11, 60, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":226,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"sugar","amount":198,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":2.5,"unit":"g"},{"name":"baking soda","amount":5,"unit":"g"},{"name":"rolled oats","amount":89,"unit":"g"},{"name":"sweetened shredded coconut","amount":85,"unit":"g"},{"name":"chocolate chips","amount":170,"unit":"g"},{"name":"crispy rice cereal","amount":67,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease or line the trays.', 'Cream the butter, both sugars, vanilla and salt until fluffy, then beat in the eggs.', 'Whisk the flour, baking powder and baking soda and mix into the wet ingredients.', 'Fold in the oats, coconut, chocolate chips and cereal until just combined.', 'Drop rounded teaspoons onto the trays, spaced apart.', 'Bake 10 to 12 minutes until golden brown. Cool on the tray or a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/ranger-cookies-recipe"}'::jsonb, false, null),
  (77, 'Holiday Butter Cookies', 'cookies', 'medium', 30, 13, 60, null, null, array['vegetarian']::text[], '[{"name":"icing sugar","amount":142,"unit":"g"},{"name":"salted butter","amount":255,"unit":"g"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"salt","amount":3,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"all-purpose flour","amount":330,"unit":"g"},{"name":"icing sugar, for the icing","amount":255,"unit":"g"},{"name":"milk","amount":39,"unit":"g"},{"name":"light corn syrup","amount":39,"unit":"g"},{"name":"coarse sparkling sugar (optional)","amount":227,"unit":"g"}]'::jsonb, array['Beat the icing sugar, butter, yolk, salt and vanilla until smooth. Mix in the flour until a dough forms, adding a splash of water if it stays dry.', 'Divide into two disks, wrap and chill 2 hours or overnight.', 'Heat the oven to 175°C. Let the dough stand 20 to 30 minutes until rollable but still cool.', 'Roll 3 to 5 mm thick on a floured surface, cut shapes and re-roll the scraps. Set on lined trays.', 'Bake 12 to 14 minutes until set and barely browned at the edges. Cool on the tray.', 'Mix the icing ingredients to a spreadable consistency, adding milk as needed, and tint if you like.', 'Decorate and top with sparkling sugar while the icing is wet, then let it set.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/holiday-butter-cookies-recipe"}'::jsonb, false, null),
  (78, 'Thumbprint Cookies', 'cookies', 'medium', 60, 13, 60, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":227,"unit":"g"},{"name":"sugar","amount":99,"unit":"g"},{"name":"light brown sugar","amount":113,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"almond flour","amount":48,"unit":"g"},{"name":"all-purpose flour","amount":330,"unit":"g"},{"name":"finely chopped nuts","amount":100,"unit":"g"},{"name":"jam or other filling","amount":255,"unit":"g"}]'::jsonb, array['Line trays with parchment.', 'Cream the butter and both sugars until very light.', 'Beat in the egg yolks (keep the whites), vanilla and salt.', 'Mix in the almond flour and most of the flour, adding the rest only if the dough is too sticky. Chill 1 hour.', 'Heat the oven to 175°C and whisk the egg whites until foamy.', 'Roll 2.5 cm balls, dip in the egg white, coat in the chopped nuts and set 5 cm apart.', 'Bake 8 minutes, press a deep thumbprint into each, then bake 4 to 6 minutes more until light golden.', 'Cool on a rack, then fill the wells.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/thumbprint-cookies-recipe"}'::jsonb, false, null),
  (79, 'Breakfast Cookies', 'cookies', 'easy', 15, 20, 22, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"peanut butter","amount":270,"unit":"g"},{"name":"light brown sugar","amount":262,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"milk","amount":74,"unit":"g"},{"name":"whole wheat flour","amount":141,"unit":"g"},{"name":"all-purpose flour","amount":40,"unit":"g"},{"name":"dry milk powder","amount":37,"unit":"g"},{"name":"ground cinnamon","amount":3,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"raisins, oats, granola, chocolate chips, coconut or nuts","amount":575,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and line two trays with parchment.', 'Beat the butter, peanut butter, brown sugar and vanilla until light and fluffy.', 'Mix in the eggs and milk, scraping the bowl.', 'On low speed mix in both flours, the dry milk, cinnamon and salt until cohesive, then fold in the add-ins.', 'Scoop 70 g mounds 5 cm apart and flatten slightly. There is no leavener, so they spread only a little.', 'Bake 18 to 22 minutes until lightly browned. Cool on the tray 5 to 8 minutes, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/breakfast-cookies-recipe"}'::jsonb, false, null),
  (80, 'Japanese Milk Bread', 'bread', 'medium', 30, 33, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"water, for the tangzhong","amount":43,"unit":"g"},{"name":"milk, for the tangzhong","amount":43,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":14,"unit":"g"},{"name":"bread flour","amount":300,"unit":"g"},{"name":"dry milk powder","amount":14,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"milk","amount":113,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"butter, melted","amount":57,"unit":"g"}]'::jsonb, array['Whisk the tangzhong water, milk and flour in a pan and cook over low heat, 3 to 5 minutes, until thick and the whisk leaves lines. Cool to lukewarm.', 'Mix the tangzhong with the dough ingredients and knead until smooth and elastic, about 15 minutes in a mixer.', 'Rest in a greased covered bowl 1 to 1.5 hours until puffy.', 'Divide into four pieces of about 172 g, then fold and roll each into a 10 cm log.', 'Set the logs seam-side down in a greased 23 cm tin and rise 40 to 50 minutes until puffy. Heat the oven to 175°C near the end.', 'Brush with milk and bake 30 to 35 minutes until golden and at least 88°C inside.', 'Cool in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/japanese-milk-bread-recipe"}'::jsonb, false, null),
  (81, 'Monkeying Around Bread', 'bread', 'easy', 20, 28, 6, 'round-20', null, array['vegetarian']::text[], '[{"name":"sugar, for the topping","amount":99,"unit":"g"},{"name":"ground cinnamon","amount":8,"unit":"g"},{"name":"lukewarm water","amount":113,"unit":"g"},{"name":"vegetable oil","amount":14,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"salt","amount":6,"unit":"g"},{"name":"sugar","amount":14,"unit":"g"},{"name":"instant yeast","amount":6,"unit":"g"},{"name":"all-purpose flour","amount":240,"unit":"g"}]'::jsonb, array['Mix the topping sugar and cinnamon and set aside.', 'Stir the water, oil, egg, salt, sugar and yeast together. Add the flour gradually, rest 5 minutes, then knead until smooth.', 'Rise 45 to 60 minutes until doubled.', 'Deflate and divide into 16 to 18 pieces of about 4 cm.', 'Dip each piece in water, roll in the cinnamon sugar and arrange in a greased 20 cm round tin. Sprinkle on any leftover topping.', 'Cover and rise 45 to 60 minutes. Heat the oven to 175°C near the end.', 'Bake 25 to 30 minutes until golden and set.', 'Turn out onto a rack right away, scrape any topping left in the tin over the bread, and pull apart to serve.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/monkeying-around-bread-recipe"}'::jsonb, false, null),
  (82, '100% Whole Wheat Sandwich Bread', 'bread', 'medium', 15, 38, 12, 'loaf-23x13', null, array['vegetarian']::text[], '[{"name":"lukewarm water","amount":301,"unit":"g"},{"name":"olive oil","amount":35,"unit":"g"},{"name":"honey","amount":106,"unit":"g"},{"name":"whole wheat flour","amount":454,"unit":"g"},{"name":"sunflower seeds, chopped","amount":35,"unit":"g"},{"name":"walnuts, chopped","amount":28,"unit":"g"},{"name":"salt","amount":9,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"}]'::jsonb, array['Mix everything into a shaggy dough.', 'Rest covered 20 minutes, then knead until fairly smooth.', 'Rise covered 1 to 2 hours until puffy and nearly doubled. Heat the oven to 175°C near the end.', 'Deflate gently, shape into a log and place in a lightly greased 23 cm tin.', 'Cover and rise 1 to 2 hours until domed 2.5 to 5 cm over the rim.', 'Bake 40 to 45 minutes, tenting with foil for the last 20, until golden and 90 to 96°C inside.', 'Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/king-arthurs-100-whole-wheat-sandwich-bread-recipe"}'::jsonb, false, null),
  (83, 'Savory Cheddar Cheese Bread', 'bread', 'easy', 20, 38, 12, 'loaf-21x11', null, array['vegetarian']::text[], '[{"name":"lukewarm milk","amount":227,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"sugar","amount":12,"unit":"g"},{"name":"extra-sharp cheddar, grated","amount":113,"unit":"g"},{"name":"Parmesan, grated","amount":28,"unit":"g"},{"name":"instant yeast","amount":4.5,"unit":"g"},{"name":"hot sauce (optional)","amount":3,"unit":"g"}]'::jsonb, array['Mix everything into a shaggy dough, then knead about 7 minutes until smooth and bouncy (or run a bread machine''s basic cycle).', 'Cover and rise 1 to 1.5 hours until puffy and nearly doubled.', 'Shape, place in a greased 21 cm tin and rise until it crests about 2.5 cm above the rim. Heat the oven to 175°C near the end.', 'Bake 35 to 40 minutes until golden and at least 88°C inside.', 'Turn out and cool completely on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/savory-cheddar-cheese-bread-recipe"}'::jsonb, false, null),
  (84, 'Vermont Whole Wheat Oatmeal Honey Bread', 'bread', 'medium', 10, 38, 24, null, null, array['vegetarian']::text[], '[{"name":"boiling water","amount":454,"unit":"g"},{"name":"rolled oats","amount":89,"unit":"g"},{"name":"light brown sugar","amount":106,"unit":"g"},{"name":"honey","amount":21,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"salt","amount":15,"unit":"g"},{"name":"ground cinnamon","amount":2.6,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"whole wheat flour","amount":170,"unit":"g"},{"name":"all-purpose flour","amount":480,"unit":"g"}]'::jsonb, array['Combine the water, oats, sugar, honey, butter, salt and cinnamon and cool to 38 to 43°C, about 10 to 15 minutes.', 'Add the yeast and flours to make a rough dough, then knead until smooth and satiny, about 10 minutes by hand.', 'Rise in a covered greased bowl 1 hour until puffy.', 'Halve the dough, shape two loaves and set in greased 21 cm tins.', 'Cover and rise 1 to 2 hours until domed 2.5 cm above the rims. Heat the oven to 175°C near the end.', 'Bake 35 to 40 minutes, tenting with foil after 25, until 88°C inside.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/vermont-whole-wheat-oatmeal-honey-bread-recipe"}'::jsonb, false, null),
  (85, 'Japanese Milk Bread Rolls', 'buns', 'medium', 30, 28, 9, 'round-20', null, array['vegetarian']::text[], '[{"name":"water, for the tangzhong","amount":43,"unit":"g"},{"name":"milk, for the tangzhong","amount":43,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":14,"unit":"g"},{"name":"cold milk","amount":113,"unit":"g"},{"name":"bread flour","amount":300,"unit":"g"},{"name":"dry milk powder","amount":14,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"salt","amount":6,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"butter, melted","amount":57,"unit":"g"},{"name":"egg, for the egg wash","amount":1,"unit":"count"},{"name":"water, for the egg wash","amount":15,"unit":"g"}]'::jsonb, array['Whisk the tangzhong water, milk and flour in a pan and cook over low heat, 3 to 5 minutes, until thick enough to leave lines.', 'Put the tangzhong in a bowl, then add the cold milk, flour, dry milk, sugar, salt, yeast, egg and butter.', 'Mix, then knead 10 to 15 minutes until smooth, elastic and tacky.', 'Rise covered 1 to 1.5 hours until puffy.', 'Deflate, divide into 8 pieces of about 82 g (or 10 of 65 g) and shape into balls.', 'Arrange in a greased 20 cm round tin, cover and rise 40 to 50 minutes until puffy. Heat the oven to 175°C.', 'Brush with the egg beaten with water and bake 25 to 30 minutes until golden and at least 88°C inside.', 'Cool 10 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/japanese-milk-bread-rolls-recipe"}'::jsonb, false, null),
  (86, 'Dark and Soft Dinner Rolls', 'buns', 'medium', 22, 24, 12, null, null, array['vegetarian']::text[], '[{"name":"warm water","amount":301,"unit":"g"},{"name":"butter","amount":57,"unit":"g"},{"name":"honey","amount":84,"unit":"g"},{"name":"molasses","amount":85,"unit":"g"},{"name":"bread flour","amount":330,"unit":"g"},{"name":"whole wheat flour","amount":220,"unit":"g"},{"name":"salt","amount":12,"unit":"g"},{"name":"cocoa powder (for colour)","amount":5,"unit":"g"},{"name":"instant yeast","amount":7.5,"unit":"g"},{"name":"yellow cornmeal, for coating","amount":20,"unit":"g"}]'::jsonb, array['Mix and knead all the dough ingredients in a mixer (paddle, then dough hook) or bread machine to a smooth, slightly sticky dough.', 'Rise in the bowl 60 to 90 minutes until just puffy.', 'Divide into 12 pieces of about 85 g and shape into 10 x 5 cm ovals.', 'Roll in cornmeal, set on a greased tray and rise covered 1 to 2 hours until puffy. Heat the oven to 175°C near the end.', 'Bake about 24 minutes until the bottoms are lightly browned or the centre is about 93°C.', 'Cool on a rack. Serve warm or at room temperature.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/dark-soft-restaurant-dinner-rolls-recipe"}'::jsonb, false, null),
  (87, 'Soft White Dinner Rolls', 'buns', 'easy', 25, 26, 16, null, null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":7,"unit":"g"},{"name":"lukewarm water","amount":225,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"sugar","amount":35,"unit":"g"},{"name":"butter, softened","amount":85,"unit":"g"},{"name":"nonfat dry milk","amount":28,"unit":"g"},{"name":"dried potato flakes","amount":39,"unit":"g"}]'::jsonb, array['Mix everything and knead until smooth, about 5 to 7 minutes in a mixer at medium-low.', 'Cover and rise in a greased bowl about 1 hour until nearly doubled.', 'Grease two 23 cm round tins. Deflate the dough gently and divide into 16 pieces.', 'Shape each into a tight ball and set 8 in each tin so they do not touch.', 'Cover and rise about 1 hour until puffy and touching. Heat the oven to 175°C.', 'Bake about 25 minutes until deep golden on top.', 'Cool 2 to 3 minutes, move to a rack and brush with melted butter if you like.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/soft-white-dinner-rolls-recipe"}'::jsonb, false, null),
  (88, 'Soft Cinnamon Rolls', 'buns', 'medium', 20, 24, 24, 'rect-33x23', null, array['vegetarian']::text[], '[{"name":"water, for the tangzhong","amount":71,"unit":"g"},{"name":"milk, for the tangzhong","amount":71,"unit":"g"},{"name":"bread flour, for the tangzhong","amount":25,"unit":"g"},{"name":"bread flour","amount":495,"unit":"g"},{"name":"dry milk powder","amount":21,"unit":"g"},{"name":"salt","amount":11,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"lukewarm milk","amount":170,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted","amount":85,"unit":"g"},{"name":"light brown sugar","amount":142,"unit":"g"},{"name":"ground cinnamon","amount":10,"unit":"g"},{"name":"icing sugar","amount":227,"unit":"g"},{"name":"butter, melted, for the icing","amount":28,"unit":"g"},{"name":"vanilla extract","amount":2,"unit":"g"},{"name":"milk or cream, for the icing","amount":36,"unit":"g"}]'::jsonb, array['Cook the tangzhong water, milk and flour over medium heat, whisking, until thick. Cool briefly.', 'Mix the tangzhong with the dough ingredients and rest covered 20 minutes.', 'Knead until smooth, elastic and slightly tacky, then rest covered 60 to 90 minutes until puffy.', 'Halve the dough. Roll each half to 45 x 20 cm, spread with the brown sugar and cinnamon, roll into a log and cut into 12 slices.', 'Space the rolls in a greased 33 x 23 cm tin and rise covered 45 to 60 minutes until crowded and puffy.', 'Heat the oven to 175°C and bake 22 to 25 minutes until set (about 87°C in the centre).', 'Mix the icing to a stiff, spreadable consistency and spread over the warm rolls.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/soft-cinnamon-rolls-recipe"}'::jsonb, false, null),
  (89, 'Sticky Buns', 'buns', 'medium', 25, 25, 16, null, null, array['vegetarian']::text[], '[{"name":"instant yeast","amount":8,"unit":"g"},{"name":"lukewarm water","amount":225,"unit":"g"},{"name":"all-purpose flour","amount":360,"unit":"g"},{"name":"butter","amount":85,"unit":"g"},{"name":"sugar","amount":35,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"dry milk powder","amount":28,"unit":"g"},{"name":"potato flakes","amount":43,"unit":"g"},{"name":"light corn syrup or maple syrup","amount":156,"unit":"g"},{"name":"rum (optional)","amount":14,"unit":"g"},{"name":"butter, melted, for the glaze","amount":43,"unit":"g"},{"name":"light brown sugar","amount":213,"unit":"g"},{"name":"pecans, diced (optional)","amount":113,"unit":"g"},{"name":"sugar, for the filling","amount":99,"unit":"g"},{"name":"ground cinnamon","amount":5,"unit":"g"},{"name":"all-purpose flour, for the filling","amount":8,"unit":"g"}]'::jsonb, array['Knead the dough ingredients until smooth: 5 to 7 minutes in a mixer on medium-low, or by hand.', 'Rise in a greased bowl 1 to 2 hours until nearly doubled.', 'Grease two 23 cm round tins. Whisk the syrup, rum and melted butter, divide between the tins and top with the brown sugar and pecans.', 'Mix the filling sugar, cinnamon and flour.', 'Roll the dough to 40 x 30 cm, spread with the filling leaving a 2.5 cm bare strip along one long edge, and roll into a log lengthways.', 'Cut into 16 slices (rinse the knife in hot water between cuts) and set 8 in each tin.', 'Cover and rise 1 to 1.5 hours until the buns touch. Heat the oven to 175°C.', 'Bake 15 minutes, tent loosely with foil and bake about 10 minutes more until light golden. Turn out onto a rack straight away so the glaze stays on the buns.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/sticky-buns-recipe"}'::jsonb, false, null),
  (90, 'Brioche Buns', 'buns', 'hard', 15, 16, 6, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":330,"unit":"g"},{"name":"dry milk powder","amount":28,"unit":"g"},{"name":"sugar","amount":25,"unit":"g"},{"name":"salt","amount":8,"unit":"g"},{"name":"instant yeast","amount":9,"unit":"g"},{"name":"eggs","amount":3,"unit":"count"},{"name":"egg yolk","amount":1,"unit":"count"},{"name":"water","amount":57,"unit":"g"},{"name":"butter, cool","amount":142,"unit":"g"},{"name":"egg white, for the wash","amount":1,"unit":"count"},{"name":"water, for the wash","amount":15,"unit":"g"}]'::jsonb, array['Mix and knead in a mixer or bread machine for 15 to 20 minutes until smooth and shiny. It starts sticky, so do not hand-knead.', 'Shape into a ball, put in a greased bowl, cover and rise 1 hour.', 'Refrigerate overnight to slow the rise and firm the dough.', 'Divide into 6 pieces, flatten each into a ball and set on a lined tray with 6 to 8 cm between them.', 'Cover and rise 1 to 3 hours until quite puffy. Heat the oven to 190°C near the end.', 'Brush with the egg white beaten with water, add seeds if you like, and bake 14 to 18 minutes, tenting with foil after 10, until at least 88°C inside.', 'Cool on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/brioche-buns-recipe"}'::jsonb, false, null),
  (91, 'Classic Key Lime Pie', 'pie', 'medium', 15, 40, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"graham cracker crumbs","amount":150,"unit":"g"},{"name":"icing sugar","amount":28,"unit":"g"},{"name":"salt","amount":0.7,"unit":"g"},{"name":"butter, melted","amount":85,"unit":"g"},{"name":"lime zest","amount":4,"unit":"g"},{"name":"egg yolks","amount":3,"unit":"count"},{"name":"sweetened condensed milk","amount":397,"unit":"g"},{"name":"lime juice","amount":152,"unit":"g"}]'::jsonb, array['Heat the oven to 165°C.', 'Mix the crumbs, icing sugar, salt and melted butter and press into a 23 cm pie dish at least 3 cm deep.', 'Bake the crust 15 minutes until slightly darker, then cool.', 'Whisk the zest and yolks on high about 4 minutes until pale and thick.', 'Beat in the condensed milk, then whip 3 minutes more.', 'Stir in the lime juice until the filling thickens.', 'Pour into the crust and bake about 25 minutes until the edges are set and the centre still wobbles (about 63°C).', 'Cool, then chill several hours. Serve with whipped cream.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/classic-key-lime-pie-recipe"}'::jsonb, false, null),
  (92, 'Apple-Pear Pie', 'pie', 'medium', 40, 70, 8, 'round-23', null, array['vegetarian']::text[], '[{"name":"double 23 cm pie crust (see All-Butter Pie Crust)","amount":1,"unit":"count"},{"name":"light brown sugar","amount":159,"unit":"g"},{"name":"Instant ClearJel","amount":11,"unit":"g"},{"name":"ground cinnamon","amount":7,"unit":"g"},{"name":"ground ginger","amount":1.5,"unit":"g"},{"name":"salt","amount":1.5,"unit":"g"},{"name":"baking apples, peeled and sliced","amount":907,"unit":"g"},{"name":"pears, peeled and sliced","amount":680,"unit":"g"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"lemon juice","amount":14,"unit":"g"},{"name":"cold butter","amount":57,"unit":"g"}]'::jsonb, array['Line a 23 cm pie dish with about two-thirds of the crust and chill.', 'Whisk the sugar, ClearJel, spices and salt.', 'Toss the fruit with the sugar mix, then stir in the vanilla and lemon juice.', 'Melt the butter in a pan, add the fruit and cook 10 to 20 minutes until softened and thickened.', 'Cool the filling completely and spoon it into the crust.', 'Top with the second crust or a lattice, crimp and cut steam vents.', 'Freeze 15 to 30 minutes while the oven heats to 220°C.', 'Brush with cream, milk or water, add sparkling sugar and bake 15 minutes at 220°C, then 50 to 60 minutes at 190°C until golden and bubbling. Cool completely before slicing.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/apple-pear-pie-recipe"}'::jsonb, false, null),
  (93, 'No-Bake Chocolate Cheesecake Bars', 'bars', 'easy', 20, 0, 16, 'square-20', null, array['vegetarian']::text[], '[{"name":"chocolate sandwich cookies","amount":227,"unit":"g"},{"name":"salt","amount":0.5,"unit":"g"},{"name":"butter, melted","amount":43,"unit":"g"},{"name":"cream cheese","amount":453,"unit":"g"},{"name":"icing sugar","amount":86,"unit":"g"},{"name":"vanilla extract","amount":13,"unit":"g"},{"name":"salt, for the filling","amount":0.5,"unit":"g"},{"name":"semisweet chocolate","amount":114,"unit":"g"},{"name":"espresso powder","amount":0.5,"unit":"g"},{"name":"heavy cream","amount":114,"unit":"g"}]'::jsonb, array['Pulse the cookies and salt to fine crumbs. Add the melted butter until the mix holds together when squeezed.', 'Press into a lined, greased 20 cm square tin and freeze at least 1 hour.', 'Beat the cream cheese, icing sugar, vanilla and salt until smooth.', 'Spread about 180 g of the filling over the crust and put the rest in a large bowl.', 'Melt the chocolate with the espresso powder in short microwave bursts, stirring between each, then stir it into the reserved filling.', 'Whip the cream to medium peaks and fold it into the chocolate filling.', 'Spread over the base and chill at least 8 hours. Slice with a hot, dry knife.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/no-bake-chocolate-cheesecake-bars-recipe"}'::jsonb, false, null),
  (94, 'Banana Chocolate Chip Muffins', 'muffins', 'easy', 10, 22, 12, null, null, array['vegetarian']::text[], '[{"name":"butter","amount":113,"unit":"g"},{"name":"sugar","amount":131,"unit":"g"},{"name":"mashed bananas","amount":227,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"milk","amount":74,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"baking soda","amount":2.5,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"all-purpose flour","amount":120,"unit":"g"},{"name":"whole wheat flour","amount":113,"unit":"g"},{"name":"chocolate chips","amount":128,"unit":"g"},{"name":"chopped walnuts, toasted (optional)","amount":113,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C and grease a 12-cup muffin tin.', 'Beat the butter and sugar until smooth.', 'Mix in the banana, then the egg, vanilla and milk.', 'Add the baking powder, baking soda, salt and both flours and mix until smooth, beating briskly to break up lumps.', 'Fold in the chocolate chips and walnuts.', 'Fill the cups generously with the thick batter and bake 20 to 23 minutes until a skewer in a centre muffin comes out clean.', 'Tilt the muffins in the tin to cool briefly, then move to a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/banana-chocolate-chip-muffins-recipe"}'::jsonb, false, null),
  (95, 'Easy Chocolate Chip Muffins', 'muffins', 'easy', 10, 23, 12, null, null, array['vegetarian']::text[], '[{"name":"all-purpose flour","amount":240,"unit":"g"},{"name":"baking powder","amount":8,"unit":"g"},{"name":"salt","amount":4,"unit":"g"},{"name":"baking soda","amount":1,"unit":"g"},{"name":"ground cinnamon","amount":0.3,"unit":"g"},{"name":"sugar","amount":149,"unit":"g"},{"name":"butter, melted and cooled","amount":57,"unit":"g"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"vanilla extract","amount":8,"unit":"g"},{"name":"whole milk","amount":170,"unit":"g"},{"name":"sour cream","amount":57,"unit":"g"},{"name":"semisweet chocolate chips","amount":170,"unit":"g"},{"name":"coarse sparkling sugar","amount":57,"unit":"g"}]'::jsonb, array['Heat the oven to 175°C with a rack in the centre and prepare a 12-cup muffin tin.', 'Whisk the flour, baking powder, salt, baking soda and cinnamon.', 'Whisk the sugar, melted butter and oil until smooth, then whisk in the eggs and vanilla.', 'Whisk in the milk and sour cream. Small bits of sour cream are fine.', 'Add the dry ingredients and mix just until combined. Some lumps are fine.', 'Fold in the chocolate chips, scoop into the cups and top with sparkling sugar.', 'Bake 20 to 25 minutes until golden and a skewer comes out nearly clean. Cool 10 minutes in the tin.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/easy-chocolate-chip-muffins-recipe"}'::jsonb, false, null),
  (96, 'Banana Muffins with Oat Streusel', 'muffins', 'easy', 20, 22, 12, null, null, array['vegetarian']::text[], '[{"name":"plain yogurt","amount":113,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"mashed bananas","amount":355,"unit":"g"},{"name":"sugar","amount":149,"unit":"g"},{"name":"oat bran","amount":113,"unit":"g"},{"name":"all-purpose flour","amount":180,"unit":"g"},{"name":"baking powder","amount":9,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"baking soda","amount":2,"unit":"g"},{"name":"ground nutmeg","amount":0.5,"unit":"g"},{"name":"light brown sugar, for the streusel","amount":53,"unit":"g"},{"name":"rolled oats","amount":23,"unit":"g"},{"name":"all-purpose flour, for the streusel","amount":14,"unit":"g"},{"name":"ground cinnamon","amount":0.6,"unit":"g"},{"name":"butter, softened","amount":14,"unit":"g"}]'::jsonb, array['Heat the oven to 190°C and prepare a 12-cup muffin tin.', 'Mix the yogurt, egg, oil, banana, sugar and oat bran and rest 10 minutes.', 'Whisk the flour, baking powder, salt, baking soda and nutmeg.', 'Rub the streusel ingredients together until crumbly.', 'Stir the wet mix into the dry. Fill the cups nearly full, since they will not rise much.', 'Top each with streusel.', 'Bake 20 to 24 minutes until set and browned. Rest 5 minutes, then unmould and serve warm.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/banana-muffins-recipe"}'::jsonb, false, null),
  (97, 'Malted Banana Muffins', 'muffins', 'medium', 30, 19, 12, null, null, array['vegetarian']::text[], '[{"name":"plain yogurt","amount":85,"unit":"g"},{"name":"eggs","amount":1,"unit":"count"},{"name":"vegetable oil","amount":50,"unit":"g"},{"name":"mashed bananas","amount":283,"unit":"g"},{"name":"whole wheat flour","amount":113,"unit":"g"},{"name":"sugar","amount":50,"unit":"g"},{"name":"malted milk powder","amount":53,"unit":"g"},{"name":"all-purpose flour","amount":120,"unit":"g"},{"name":"baking powder","amount":6,"unit":"g"},{"name":"baking soda","amount":1,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"semisweet chocolate chips (optional)","amount":128,"unit":"g"},{"name":"cocoa powder, for the swirl","amount":21,"unit":"g"},{"name":"malted milk powder, for the swirl","amount":53,"unit":"g"},{"name":"icing sugar","amount":57,"unit":"g"},{"name":"Instant ClearJel","amount":3,"unit":"g"},{"name":"butter, melted","amount":28,"unit":"g"},{"name":"warm milk","amount":14,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and line a 12-cup muffin tin.', 'Mix the yogurt, egg, oil and bananas, then stir in the whole wheat flour.', 'Sift the sugar, malted milk powder, all-purpose flour, baking powder, baking soda and salt, fold into the wet mix and add the chocolate chips.', 'Sift the swirl cocoa, malted milk powder, icing sugar and ClearJel. Stir in the warm melted butter and milk until smooth, and spoon into a piping bag.', 'Fill the cups about three-quarters full with batter and pipe swirl dollops just under the surface.', 'Drag a knife through each muffin to marble it.', 'Bake 18 to 20 minutes until the tops spring back. Cool 5 minutes in the tin, then on a rack.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/malted-banana-muffins-recipe"}'::jsonb, false, null),
  (98, 'Hot Cross Muffins', 'muffins', 'easy', 30, 20, 12, null, null, array['vegetarian']::text[], '[{"name":"golden raisins","amount":149,"unit":"g"},{"name":"rum or water","amount":28,"unit":"g"},{"name":"all-purpose flour","amount":300,"unit":"g"},{"name":"baking powder","amount":12,"unit":"g"},{"name":"sugar","amount":66,"unit":"g"},{"name":"salt","amount":3,"unit":"g"},{"name":"ground cinnamon","amount":1,"unit":"g"},{"name":"ground nutmeg","amount":1.5,"unit":"g"},{"name":"ground allspice","amount":0.5,"unit":"g"},{"name":"milk","amount":340,"unit":"g"},{"name":"eggs","amount":2,"unit":"count"},{"name":"butter, melted","amount":113,"unit":"g"},{"name":"candied mixed peel or extra dried fruit","amount":85,"unit":"g"},{"name":"icing sugar","amount":142,"unit":"g"},{"name":"butter, softened","amount":28,"unit":"g"},{"name":"vanilla extract","amount":4,"unit":"g"},{"name":"milk or cream, for the icing","amount":28,"unit":"g"}]'::jsonb, array['Heat the oven to 200°C and prepare a 12-cup muffin tin.', 'Soak the raisins in the warmed rum or water while you prepare the rest.', 'Whisk the flour, baking powder, sugar, salt and spices.', 'Beat the milk and eggs, stir in the melted butter, then add to the dry mix with the fruit and peel and stir until just combined.', 'Scoop a generous 60 ml into each cup and bake 20 to 25 minutes until a skewer comes out clean. Cool on a rack.', 'Beat the icing sugar, soft butter, vanilla and milk until smooth, adding liquid until pipeable.', 'Pipe a cross on each cooled muffin.']::text[], '{"name":"King Arthur Baking","url":"https://www.kingarthurbaking.com/recipes/hot-cross-muffins-recipe"}'::jsonb, false, null)
